## 六、空间优化

用三个变量 $f_1,f_2,f_3$ 分别表示最近的三个 $f$ 值。

```py [sol-Python3]
class Solution:
    def stoneGameIII(self, stoneValue: List[int]) -> str:
        suf_sum = f1 = f2 = f3 = 0
        for val in reversed(stoneValue):
            suf_sum += val
            f1, f2, f3 = suf_sum - min(f1, f2, f3), f1, f2

        diff = f1 - (suf_sum - f1)
        if diff == 0:
            return "Tie"
        return "Alice" if diff > 0 else "Bob"
```

```java [sol-Java]
class Solution {
    public String stoneGameIII(int[] stoneValue) {
        int sufSum = 0;
        int f1 = 0;
        int f2 = 0;
        int f3 = 0;
        for (int i = stoneValue.length - 1; i >= 0; i--) {
            sufSum += stoneValue[i];
            int newF = sufSum - Math.min(Math.min(f1, f2), f3);
            f3 = f2;
            f2 = f1;
            f1 = newF;
        }

        int diff = f1 - (sufSum - f1);
        if (diff == 0) {
            return "Tie";
        }
        return diff > 0 ? "Alice" : "Bob";
    }
}
```

