func stoneGameIII(stoneValue []int) string {
	const k = 3
	n := len(stoneValue)
	f := make([]int, n+1)
	q := []int{n}
	sufSum := 0 // stoneValue 的后缀和

	for i := n - 1; i >= 0; i-- {
		sufSum += stoneValue[i]

		// 窗口向左滑动
		// 1. 右边出，保证窗口元素下标在 [i+1, i+k] 中
		if q[0] > i+k { // 离开窗口
			q = q[1:]
		}

		// 2. 计算转移
		f[i] = sufSum - f[q[0]]

		// 3. 左边入，先去掉无用数据，再把 i 入队
		for len(q) > 0 && f[q[len(q)-1]] >= f[i] { // f[i] 更小（或者相等）
			q = q[:len(q)-1]
		}
		q = append(q, i)
	}

	diff := f[0]*2 - sufSum
	if diff == 0 {
		return "Tie"
	}
	if diff > 0 {
		return "Alice"
	}
	return "Bob"
}
