func stoneGameII(s []int) int {
    n := len(s)
    for i := n - 2; i >= 0; i-- {
        s[i] += s[i+1] // 后缀和
    }

    memo := make([][]int, n-1)
    for i := range memo {
        memo[i] = make([]int, (n+1)/4+1)
        for j := range memo[i] {
            memo[i][j] = -1 // -1 表示没有计算过
        }
    }

    var dfs func(int, int) int
    dfs = func(i, m int) int {
        if i+m*2 >= n { // 全拿
            return s[i]
        }
        p := &memo[i][m]
        if *p != -1 {
            return *p
        }
        mn := math.MaxInt
        for x := 1; x <= m*2; x++ {
            mn = min(mn, dfs(i+x, max(m, x)))
        }
        *p = s[i] - mn
        return *p
    }

    return dfs(0, 1)
}
