## 四、单调队列优化

讨论 $\max(m,x)$ 的值：

- 当 $x\le m$ 时，$\max(m,x) = m$。
- 当 $x> m$ 时，$\max(m,x) = x$。

当 $i+2m<n$ 时，状态转移方程可以分成两部分：

$$
f[i][m] = s_i - \min
\begin{cases}
& \min\limits_{j=i+1}^{i+m} f[j][m]    \\
& \min\limits_{x=m+1}^{2m} f[i+x][x]    \\
\end{cases}
$$

第一部分，我们求的是长为 $m$ 的**滑动窗口最小值**（窗口向上滑动），做法同 [239. 滑动窗口最大值](https://leetcode.cn/problems/sliding-window-maximum/)，原理请看 [单调队列【基础算法精讲 27】](https://www.bilibili.com/video/BV1bM411X72E/)。

第二部分，在 $f$ 矩阵上看，我们求的是一个斜向的滑动窗口最小值。左上角在 $(i+m+1,m+1)$，右下角在 $(i+2m,2m)$，窗口长度为 $m$。窗口向右下滑动。

```py [sol-Python3]
class Solution:
    def stoneGameII(self, piles: list[int]) -> int:
        n = len(piles)
        f = [[0] * (n + 1) for _ in range(n)]
        col_q = [deque() for _ in range(n + 1)]  # 每列的滑动窗口最小值（窗口向上滑动）

        s = 0
        for i in range(n - 1, -1, -1):
            s += piles[i]
            diag_q = deque()  # 斜向的滑动窗口最小值（窗口向右下滑动）
            for m in range(1, i // 2 + 2):
                if i + m * 2 >= n:  # 全拿
                    f[i][m] = s
                    continue

                # f[i+1][m] 进入列窗口
                q = col_q[m]
                while q and f[q[-1]][m] >= f[i + 1][m]:
                    q.pop()
                q.append(i + 1)

                # 队首离开列窗口
                if q[0] > i + m:
                    q.popleft()

                # f[i+m*2-1][m*2-1] 和 f[i+m*2][m*2] 进入斜向窗口
                for x in range(m * 2 - 1, m * 2 + 1):
                    while diag_q and f[i + diag_q[-1]][diag_q[-1]] >= f[i + x][x]:
                        diag_q.pop()
                    diag_q.append(x)

                # 队首离开斜向窗口
                if diag_q[0] <= m:
                    diag_q.popleft()

                f[i][m] = s - min(f[q[0]][m], f[i + diag_q[0]][diag_q[0]])

        return f[0][1]
```

```java [sol-Java]
class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[][] f = new int[n][n + 1];
        ArrayDeque<Integer>[] colQ = new ArrayDeque[n + 1];
        Arrays.setAll(colQ, _ -> new ArrayDeque<>()); // 每列的滑动窗口最小值（窗口向上滑动）

        for (int i = n - 1, s = 0; i >= 0; i--) {
            s += piles[i];
            ArrayDeque<Integer> diagQ = new ArrayDeque<>(); // 斜向的滑动窗口最小值（窗口向右下滑动）
            for (int m = 1; m <= i / 2 + 1; m++) {
                if (i + m * 2 >= n) { // 全拿
                    f[i][m] = s;
                    continue;
                }

                // f[i+1][m] 进入列窗口
                ArrayDeque<Integer> q = colQ[m];
                while (!q.isEmpty() && f[q.peekLast()][m] >= f[i + 1][m]) {
                    q.pollLast();
                }
                q.offerLast(i + 1);

                // 队首离开列窗口
                if (q.peekFirst() > i + m) {
                    q.pollFirst();
                }

                // f[i+m*2-1][m*2-1] 和 f[i+m*2][m*2] 进入斜向窗口
                for (int x = m * 2 - 1; x <= m * 2; x++) {
                    while (!diagQ.isEmpty() && f[i + diagQ.peekLast()][diagQ.peekLast()] >= f[i + x][x]) {
                        diagQ.pollLast();
                    }
                    diagQ.offerLast(x);
                }

                // 队首离开斜向窗口
                if (diagQ.peekFirst() <= m) {
                    diagQ.pollFirst();
                }

                f[i][m] = s - Math.min(f[q.peekFirst()][m], f[i + diagQ.peekFirst()][diagQ.peekFirst()]);
            }
        }

        return f[0][1];
    }
}
