class Solution {
public:
    int stoneGameII(vector<int>& piles) {
        int n = piles.size();
        vector f(n, vector<int>(n + 1));
        vector<deque<int>> col_q(n + 1); // 每列的滑动窗口最小值（窗口向上滑动）

        for (int i = n - 1, s = 0; i >= 0; i--) {
            s += piles[i];
            deque<int> diag_q; // 斜向的滑动窗口最小值（窗口向右下滑动）
            for (int m = 1; m <= i / 2 + 1; m++) {
                if (i + m * 2 >= n) { // 全拿
                    f[i][m] = s;
                    continue;
                }

                // f[i+1][m] 进入列窗口
                auto& q = col_q[m];
                while (!q.empty() && f[q.back()][m] >= f[i + 1][m]) {
                    q.pop_back();
                }
                q.push_back(i + 1);

                // 队首离开列窗口
                if (q.front() > i + m) {
                    q.pop_front();
                }

                // f[i+m*2-1][m*2-1] 和 f[i+m*2][m*2] 进入斜向窗口
                for (int x = m * 2 - 1; x <= m * 2; x++) {
                    while (!diag_q.empty() && f[i + diag_q.back()][diag_q.back()] >= f[i + x][x]) {
                        diag_q.pop_back();
                    }
                    diag_q.push_back(x);
                }

                // 队首离开斜向窗口
                if (diag_q.front() <= m) {
                    diag_q.pop_front();
                }

                f[i][m] = s - min(f[q.front()][m], f[i + diag_q.front()][diag_q.front()]);
            }
        }

        return f[0][1];
    }
};
