## 方法四：随机

在 $\textit{nums}$ 中随机选择两个下标不同的元素，如果两数相等，即找到了重复元素。

首先，在 $[0,n-1]$ 中随机一个数，作为下标 $i$。

然后，我们要在 $[0,i-1]\cup [i+1,n-1]$ 中随机另一个下标 $j$。

但是，标准库只支持在一个连续范围中随机元素，如何在一个间断的区间中随机元素呢？

考虑**映射**，把 $[0,n-2]$ 映射到 $[0,i-1]\cup [i+1,n-1]$ 中：

$$
f(x) =
\begin{cases} 
x, & 0\le x \le i-1     \\
x+1, & i\le x \le n-2     \\
\end{cases}
$$

具体地，在 $[0,n-2]$ 中随机一个数 $x$：

- 如果 $x < i$，那么把 $x$ 作为下标 $j$。
- 如果 $x \ge i$，那么把 $x+1$ 作为下标 $j$。

```py [sol-Python3]
class Solution:
    def repeatedNTimes(self, nums: List[int]) -> int:
        n = len(nums)
        while True:
            # 在 [0, n-1] 中随机生成两个不同下标
            i = randrange(n)
            j = randrange(n - 1)
            if j >= i:
                j += 1
            if nums[i] == nums[j]:
                return nums[i]
```

```java [sol-Java]
class Solution {
    private static final Random rand = new Random();

    public int repeatedNTimes(int[] nums) {
        int n = nums.length;
        while (true) {
            // 在 [0, n-1] 中随机生成两个不同下标
            int i = rand.nextInt(n);
            int j = rand.nextInt(n - 1);
            if (j >= i) {
                j++;
            }
            if (nums[i] == nums[j]) {
                return nums[i];
            }
        }
    }
}
```

```cpp [sol-C++]
class Solution {
public:
    int repeatedNTimes(vector<int>& nums) {
        int n = nums.size();
        mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
        while (true) {
            // 在 [0, n-1] 中随机生成两个不同下标
            int i = uniform_int_distribution<>(0, n - 1)(rng);
            int j = uniform_int_distribution<>(0, n - 2)(rng);
            if (j >= i) {
                j++;
            }
            if (nums[i] == nums[j]) {
                return nums[i];
            }
        }
    }
};
