```py [sol-Python3]
class Solution:
    def generateSchedule(self, n: int) -> List[List[int]]:
        if n < 5:
            return []

        ans = []

        # 单独处理 d=1
        for i in range(0, n, 2):
            ans.append([i, (i + 1) % n])
        for i in range(1, n, 2):
            ans.append([i, (i + 1) % n])
        if n % 2 == 0:  # 保证 d=1 的最后一场比赛与 d=2 的第一场比赛无冲突
            ans[-1], ans[-2] = ans[-2], ans[-1]

        # 处理 d=2,3,...,n-2
        for d in range(2, n - 1):
            for i in range(n):
                ans.append([i, (i + d) % n])

        # 单独处理 d=n-1（或者说 d=-1）
        for i in range(1, n, 2):
            ans.append([i, (i - 1) % n])
        if n % 2 == 0:  # 保证 i 为奇数时的最后一场比赛与 i 为偶数时的第一场比赛无冲突
            ans[-1], ans[-2] = ans[-2], ans[-1]
        for i in range(0, n, 2):
            ans.append([i, (i - 1) % n])

        return ans
```

```java [sol-Java]
class Solution {
    public int[][] generateSchedule(int n) {
        if (n < 5) {
            return new int[][]{};
        }

        int[][] ans = new int[n * (n - 1)][];
        int idx = 0;

        // 单独处理 d=1
        for (int i = 0; i < n; i += 2) {
            ans[idx++] = new int[]{i, (i + 1) % n};
        }
        for (int i = 1; i < n; i += 2) {
            ans[idx++] = new int[]{i, (i + 1) % n};
        }
        if (n % 2 == 0) { // 保证 d=1 的最后一场比赛与 d=2 的第一场比赛无冲突
            swap(ans, idx - 1, idx - 2);
        }

        // 处理 d=2,3,...,n-2
        for (int d = 2; d < n - 1; d++) {
            for (int i = 0; i < n; i++) {
                ans[idx++] = new int[]{i, (i + d) % n};
            }
        }

        // 单独处理 d=n-1
        for (int i = 1; i < n; i += 2) {
            ans[idx++] = new int[]{i, (i + n - 1) % n};
        }
        if (n % 2 == 0) { // 保证 i 为奇数时的最后一场比赛与 i 为偶数时的第一场比赛无冲突
            swap(ans, idx - 1, idx - 2);
        }
        for (int i = 0; i < n; i += 2) {
            ans[idx++] = new int[]{i, (i + n - 1) % n};
        }

        return ans;
    }

    private void swap(int[][] a, int i, int j) {
        int[] tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}
```

