```cpp [sol-C++]
class Solution {
    vector<vector<int>> gen(vector<vector<int>> perm) {
        vector<vector<int>> ans;
        ans.push_back(perm.back());
        perm.pop_back();
        while (!perm.empty()) {
            bool found = false;
            // 倒着遍历，这样删除的时候 i 更大，移动的数据少
            for (int i = perm.size() - 1; i >= 0; i--) {
                auto& p = perm[i];
                auto& last = ans.back();
                if (p[0] != last[0] && p[0] != last[1] && p[1] != last[0] && p[1] != last[1]) {
                    // p 和上一场比赛无冲突
                    ans.push_back(p);
                    perm.erase(perm.begin() + i);
                    found = true;
                    break; // 找下一场比赛
                }
            }
            if (!found) {
                return {};
            }
        }
        return ans;
    };

public:
    vector<vector<int>> generateSchedule(int n) {
        if (n < 5) {
            return {};
        }

        // 初始化赛程排列
        vector<vector<int>> perm;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    perm.push_back({i, j});
                }
            }
        }

        mt19937 rng(chrono::steady_clock::now().time_since_epoch().count()); // 或者 mt19937 rng(1);
        while (true) {
            ranges::shuffle(perm, rng); // 随机打乱
            auto ans = gen(perm);
            if (!ans.empty()) {
                return ans;
            }
        }
    }
};
