func generateSchedule(n int) [][]int {
	if n < 5 {
		return nil
	}

	// 初始化赛程排列
	perm := make([][]int, 0, n*(n-1))
	for i := range n {
		for j := range n {
			if j != i {
				perm = append(perm, []int{i, j})
			}
		}
	}

	for {
		rand.Shuffle(len(perm), func(i, j int) { perm[i], perm[j] = perm[j], perm[i] })
		if ans := gen(slices.Clone(perm)); ans != nil {
			return ans
		}
	}
