    vector<int> minOperations(vector<int>& nums) {
        for (int& x : nums) {
            int j = ranges::lower_bound(palindromes, x) - palindromes.begin();
            // 变成 >= x 的二进制回文数，或者变成 < x 的二进制回文数
            x = min(palindromes[j] - x, x - palindromes[j - 1]);
        }
        return nums;
    }
};
