        auto solve = [&](int i, int j, int mid_d) -> long long {
            // 中间 [i+1, m-2-i] 需要补满 0 < cnt[k] < k 的数字 k，然后左半剩余数位可以随便填
            int free = m / 2 - 1 - i; // 统计左半（不含正中间）可以随便填的数位个数
