            int m = r - l + 1;
            int q = 1 << w;
            long long pow_q = pow(q, m);
            long long inv_q1 = pow(q - 1, MOD - 2);
            long long s = r * (pow_q - 1) % MOD * inv_q1 - (q - m * pow_q + (m - 1) * pow_q % MOD * q) % MOD * inv_q1 % MOD * inv_q1;
            ans = (ans * pow_q + s) % MOD;
        }
        return (ans + MOD) % MOD; // 保证结果非负
