func maximumBags(capacity, rocks []int, additionalRocks int) (ans int) {
	for i := range capacity {
		capacity[i] -= rocks[i]
	}
	sort.Ints(capacity) // 先装剩余最小的
	for _, leftSpace := range capacity {
		if leftSpace > additionalRocks { // 无法装满，那后续也无法装满（因为排序了）
