1. 用哈希表（或者数组）统计每个元素的出现次数。
2. 把出现次数从大到小排序，得到 $\textit{cnt}$ 数组。
3. 遍历 $\textit{cnt}$，计算前缀和 $s$，直到 $s \ge \dfrac{n}{2}$ 为止，返回此时的下标加一，即为答案。

注意题目保证 $n$ 是偶数。

## 哈希表写法

```py [sol-Python3]
class Solution:
    def minSetSize(self, arr: List[int]) -> int:
        cnt = sorted(Counter(arr).values(), reverse=True)
        m = len(arr) // 2
        for i, s in enumerate(accumulate(cnt)):
            if s >= m:
                return i + 1
```

```java [sol-Java]
class Solution {
    public int minSetSize(int[] arr) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : arr) {
            freq.merge(x, 1, Integer::sum); // freq[x]++
        }

        List<Integer> cnt = new ArrayList<>(freq.values());
        cnt.sort((a, b) -> b - a);

        int s = 0;
        for (int i = 0; ; i++) {
            s += cnt.get(i);
            if (s >= arr.length / 2) {
                return i + 1;
            }
        }
    }
}
```

```cpp [sol-C++]
class Solution {
public:
    int minSetSize(vector<int>& arr) {
        unordered_map<int, int> freq;
        for (int x : arr) {
            freq[x]++;
        }

        vector<int> cnt;
        for (auto& [_, c] : freq) {
            cnt.push_back(c);
        }
        ranges::sort(cnt, greater());

        int s = 0;
        for (int i = 0; ; i++) {
            s += cnt[i];
            if (s >= arr.size() / 2) {
                return i + 1;
            }
        }
    }
};
```

```go [sol-Go]
