	freq := map[int]int{}
	for _, x := range arr {
		freq[x]++
	}

	cnt := slices.SortedFunc(maps.Values(freq), func(a, b int) int { return b - a })

	s := 0
	for i, c := range cnt {
		s += c
		if s >= len(arr)/2 {
			return i + 1
		}
	}
	panic("impossible")
}
