```java [sol-Java]
class Solution {
    public int minSetSize(int[] arr) {
        int mx = 0;
        for (int x : arr) {
            mx = Math.max(mx, x);
        }

        int[] cnt = new int[mx + 1];
        for (int x : arr) {
            cnt[x]++;
        }
        Arrays.sort(cnt);

        int s = 0;
        for (int i = mx; ; i--) {
            s += cnt[i];
            if (s >= arr.length / 2) {
                return mx + 1 - i;
            }
        }
    }
}
