        sum[j] += x;
        mn[j] = MIN(mn[j], x);
    }

    long long m = mass;
    for (int i = 0; i < max_width; i++) {
        if (mn[i] == INT_MAX) {
            continue;
        }
        if (m < mn[i]) { // 无法摧毁这组的任意小行星
