impl Solution {
    pub fn asteroids_destroyed(mass: i32, asteroids: Vec<i32>) -> bool {
        let mx = *asteroids.iter().max().unwrap();
        let max_width = 32 - mx.leading_zeros() as usize;
        let mut mn = vec![i32::MAX; max_width];
        let mut sum = vec![0; max_width];

