本题没有负数，所以每排都可以取恰好 $\textit{limits}[i]$ 个数。

为了最大化元素和，每排取最大的 $\textit{limits}[i]$ 个数。

然后再取这些数中最大的 $k$ 个数，求和即为答案。

具体请看 [视频讲解](https://www.bilibili.com/video/BV1hiAUeWEUG/)，欢迎点赞关注~

```py [sol-Python3]
class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        a = []
        for row, limit in zip(grid, limits):
            row.sort(reverse=True)
            a += row[:limit]

        a.sort(reverse=True)
        return sum(a[:k])
```

```java [sol-Java]
// 更快的写法见【数组】
class Solution {
    public long maxSum(int[][] grid, int[] limits, int k) {
        List<Integer> a = new ArrayList<>();
        for (int i = 0; i < grid.length; i++) {
            int[] row = grid[i];
            Arrays.sort(row);
            for (int j = row.length - limits[i]; j < row.length; j++) {
                a.add(row[j]);
            }
        }

        a.sort(Collections.reverseOrder());
        long ans = 0;
        for (int i = 0; i < k; i++) {
            ans += a.get(i);
        }
        return ans;
    }
}
```

```java [sol-Java 数组]
class Solution {
    public long maxSum(int[][] grid, int[] limits, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int[] a = new int[m * n];
        int size = 0;
        for (int i = 0; i < m; i++) {
            int[] row = grid[i];
            Arrays.sort(row);
            for (int j = n - limits[i]; j < n; j++) {
                a[size++] = row[j];
            }
        }

        Arrays.sort(a, 0, size);
        long ans = 0;
        for (int i = size - k; i < size; i++) {
            ans += a[i];
        }
        return ans;
    }
}
