class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> idx(n);
        ranges::iota(idx, 0);
        ranges::nth_element(idx, idx.begin() + k, {}, [&](int i) { return -nums[i]; });

        vector<int8_t> in_seq(n);
        for (int i = 0; i < k; i++) {
            in_seq[idx[i]] = true; // 标记前 k 大元素的下标
        }

        idx.resize(k);
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (in_seq[i]) {
                idx[j++] = nums[i];
            }
        }
        return idx;
    }
};
