impl Solution {
    pub fn max_subsequence(nums: Vec<i32>, k: i32) -> Vec<i32> {
        // 创建下标数组，对下标数组排序
        let mut idx = (0..nums.len()).collect::<Vec<_>>();
        idx.sort_unstable_by_key(|&i| -nums[i]);

        // 对前 k 个下标排序
        idx.truncate(k as usize);
        idx.sort_unstable();

        // 取出 nums 的子序列
        idx.into_iter().map(|i| nums[i]).collect()
    }
}
