class Solution {
    public long maxPoints(int[] a, int[] b, int k) {
        int n = a.length;
        long ans = 0;
        int idx = 0;

        for (int i = 0; i < n; i++) {
            ans += a[i];
            int d = b[i] - a[i];
            if (d > 0) {
                a[idx++] = d; // 把 a 当作 diff
            }
        }

        Arrays.sort(a, 0, idx);
        for (int i = Math.max(idx - (n - k), 0); i < idx; i++) {
            ans += a[i];
        }
        return ans;
    }
}
