impl Solution {
    pub fn maximum_score(mut cards: Vec<i32>, cnt: i32) -> i32 {
        cards.sort_unstable_by(|a, b| b.cmp(a));
        let cnt = cnt as usize;
        let s = cards[..cnt].iter().sum::<i32>(); // 最大的 cnt 个数之和
        if s % 2 == 0 { // s 是偶数
            return s;
