```java [sol-Java]
class Solution {
    public long maxTotal(int[] value, int[] limit) {
        int n = value.length;
        List<Integer>[] groups = new ArrayList[n + 1];
        Arrays.setAll(groups, _ -> new ArrayList<>());
        for (int i = 0; i < n; i++) {
            groups[limit[i]].add(value[i]);
        }

        long ans = 0;
        for (int lim = 1; lim <= n; lim++) {
            List<Integer> a = groups[lim];
            if (lim < a.size()) {
                // 只取最大的 lim 个数
                a.sort(Collections.reverseOrder());
                a = a.subList(0, lim);
            }
            for (int x : a) {
                ans += x;
            }
        }
        return ans;
    }
}
```

```cpp [sol-C++]
class Solution {
public:
    long long maxTotal(vector<int>& value, vector<int>& limit) {
        int n = value.size();
        vector<vector<int>> groups(n + 1);
        for (int i = 0; i < n; i++) {
            groups[limit[i]].push_back(value[i]);
        }

        long long ans = 0;
        for (int lim = 1; lim <= n; lim++) {
            auto& a = groups[lim];
            if (lim < a.size()) {
                // 只取最大的 lim 个数
                ranges::nth_element(a, a.begin() + lim, greater());
                a.resize(lim);
            }
            ans += reduce(a.begin(), a.end(), 0LL);
        }
        return ans;
    }
};
