    public int matchPlayersAndTrainers(int[] players, int[] trainers) {
        Arrays.sort(players);
        Arrays.sort(trainers);
        int n = players.length;
        int m = trainers.length;
        int j = 0;
        for (int i = 0; i < n; i++) {
            int p = players[i];
            while (j < m && trainers[j] < p) {
                j++;
            }
            if (j == m) { // 无法找到匹配的训练师
                return i;
            }
            j++; // 匹配一位训练师
        }
        return n; // 所有运动员都有匹配的训练师
    }
}
```

