```go [sol-Go]
func advantageCount(nums1, nums2 []int) []int {
    slices.Sort(nums1)

    n := len(nums1)
    idx := make([]int, n)
    for i := range idx {
        idx[i] = i
    }
    slices.SortFunc(idx, func(i, j int) int { return nums2[i] - nums2[j] })

    ans := make([]int, n)
    left, right := 0, n-1
    for _, x := range nums1 {
        if x > nums2[idx[left]] {
            ans[idx[left]] = x // 用下等马比下等马
            left++
        } else {
            ans[idx[right]] = x // 用下等马比上等马
            right--
        }
    }
    return ans
}
```

