class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        ans = 0
        for col in zip(*grid):
            pre = -inf
            for x in col:
                ans += max(pre + 1 - x, 0)
                pre = max(pre + 1, x)
        return ans
