func minimumBuckets(street string) (ans int) {
	bucketPos := -2 // 上一个水桶的放置位置
	for i, ch := range street {
		if ch == 'H' { // 遍历每个房屋
			if bucketPos == i-1 { // 左侧已有水桶，不做任何处理
