```go [sol-Go]
func minDeletionSize(strs []string) (ans int) {
	n, m := len(strs), len(strs[0])
	a := make([]string, n) // 最终得到的字符串数组
next:
	for j := range m {
		for i := range n - 1 {
			if a[i]+string(strs[i][j]) > a[i+1]+string(strs[i+1][j]) {
				// j 列不是升序，必须删
				ans++
				continue next
			}
		}
		// j 列是升序，不删更好
		for i, s := range strs {
			a[i] += string(s[j])
		}
	}
	return
}
