```rust [sol-Rust]
use std::collections::HashMap;

impl Solution {
    pub fn reorganize_string(s: String) -> String {
        let n = s.len();
        let mut count = HashMap::new();
        for c in s.bytes() {
            *count.entry(c).or_insert(0) += 1;
        }

        let mut a = count.into_iter().collect::<Vec<_>>();
        // 按出现次数从大到小排序
        a.sort_unstable_by(|p, q| q.1.cmp(&p.1));
        let m = a[0].1;
        if m > n - m + 1 {
            return "".to_string();
        }

        let mut ans = vec![b'\0'; n];
        let mut i = 0;
        for (ch, cnt) in a {
            for _ in 0..cnt {
                ans[i] = ch;
                i += 2;
                if i >= n {
                    i = 1; // 填完偶数填奇数
                }
            }
        }
        unsafe { String::from_utf8_unchecked(ans) }
    }
}
```

#### 复杂度分析

- 时间复杂度：$\mathcal{O}(n + |\Sigma|\log |\Sigma|)$，其中 $n$ 是 $s$ 的长度，$|\Sigma|$ 为字符集合的大小，本题字符均为小写字母，所以 $|\Sigma|=26$。
- 空间复杂度：$\mathcal{O}(n + |\Sigma|)$。如果不考虑返回值的空间，C++ 为 $\mathcal{O}(|\Sigma|)$。

## 写法二：不排序

只需要先填出现次数最多的字母，其余字母无需排序。

比如 $s=\texttt{aaabb}$：

- 先填 $\texttt{a}$ 再填 $\texttt{b}$，得到 $\texttt{ababa}$。
- 先填 $\texttt{b}$ 再填 $\texttt{a}$，得到 $\texttt{babaa}$，不符合要求。

```py [sol-Python3]
class Solution:
    def reorganizeString(self, s: str) -> str:
        n = len(s)
        count = Counter(s)
        ch, m = count.most_common(1)[0]
        if m > n - m + 1:
            return ""

        ans = [''] * n
        i = m * 2
        ans[:i:2] = [ch] * m  # 先填出现次数最多的字母
        del count[ch]

        # 再填其它字母
        for ch, cnt in count.items():
            for _ in range(cnt):
                if i >= n:
                    i = 1  # 填完偶数填奇数
                ans[i] = ch
                i += 2
        return ''.join(ans)
```

```java [sol-Java]
class Solution {
    public String reorganizeString(String s) {
        int n = s.length();
        int[] count = new int[26];
        int m = 0;
        char mch = 0;
        for (char ch : s.toCharArray()) {
            if (++count[ch - 'a'] > m) {
                m = count[ch - 'a'];
                mch = ch;
            }
        }
        if (m > n - m + 1) {
            return "";
        }

        char[] ans = new char[n];
        int i = 0;
        for (; m-- > 0; i += 2) {
            ans[i] = mch; // 先填出现次数最多的字母
        }
        count[mch - 'a'] = 0;

        // 再填其它字母
        for (int j = 0; j < 26; j++) {
            int cnt = count[j];
            while (cnt-- > 0) {
                if (i >= n) {
                    i = 1; // 填完偶数填奇数
                }
                ans[i] = (char) ('a' + j);
                i += 2;
            }
        }
        return new String(ans);
    }
}
```

