```go [sol-Go]
func reorganizeString(s string) string {
    n := len(s)
    count := [26]int{}
    m, mch := 0, byte(0)
    for _, ch := range s {
        count[ch-'a']++
        if count[ch-'a'] > m {
            m = count[ch-'a']
            mch = byte(ch)
        }
    }
    if m > n-m+1 {
        return ""
    }

    ans := make([]byte, n)
    i := 0
    for ; m > 0; m-- {
        ans[i] = mch // 先填出现次数最多的字母
        i += 2
    }
    count[mch-'a'] = 0

    // 再填其它字母
    for j, cnt := range count {
        for ; cnt > 0; cnt-- {
            if i >= n {
                i = 1 // 填完偶数填奇数
            }
            ans[i] = byte('a' + j)
            i += 2
        }
    }
    return string(ans)
}
```

```js [sol-JavaScript]
var reorganizeString = function(s) {
    const n = s.length;
    const count = Array(26).fill(0);
    let m = 0;
    let mch;
    for (const ch of s) {
        const idx = ch.charCodeAt(0) - 'a'.charCodeAt(0);
        if (++count[idx] > m) {
            m = count[idx];
            mch = ch;
        }
    }
    if (m > n - m + 1) {
        return "";
    }

    const ans = Array(n);
    let i = 0;
    for (; m--; i += 2) {
        ans[i] = mch; // 先填出现次数最多的字母
    }
    count[mch.charCodeAt(0) - 'a'.charCodeAt(0)] = 0;

    // 再填其它字母
    for (let j = 0; j < 26; j++) {
        let cnt = count[j];
        while (cnt--) {
            if (i >= n) {
                i = 1; // 填完偶数填奇数
            }
            ans[i] = String.fromCharCode('a'.charCodeAt(0) + j);
            i += 2;
        }
    }
    return ans.join('');
}
```

```rust [sol-Rust]
impl Solution {
    pub fn reorganize_string(s: String) -> String {
        let n = s.len();
        let mut count = vec![0; 26];
        let mut m = 0;
        let mut mch = b'a';
        for ch in s.bytes() {
            let idx = (ch - b'a') as usize;
            count[idx] += 1;
            if count[idx] > m {
                m = count[idx];
                mch = ch;
            }
        }
        if m > n - m + 1 {
            return "".to_string();
        }

        let mut ans = vec![b'\0'; n];
        let mut i = 0;
        for _ in 0..m {
            ans[i] = mch; // 先填出现次数最多的字母
            i += 2;
        }
        count[(mch - b'a') as usize] = 0;

        // 再填其它字母
        for (j, &cnt) in count.iter().enumerate() {
            for _ in 0..cnt {
                if i >= n {
                    i = 1; // 填完偶数填奇数
                }
                ans[i] = b'a' + j as u8;
                i += 2;
            }
        }
        unsafe { String::from_utf8_unchecked(ans) }
    }
}
```

