```c [sol-C]
#define MIN(a, b) ((b) < (a) ? (b) : (a))
#define MAX(a, b) ((b) > (a) ? (b) : (a))

long long numberOfWeeks(int* milestones, int milestonesSize) {
    long long s = 0;
    int m = 0;
    for (int i = 0; i < milestonesSize; i++) {
        int x = milestones[i];
        s += x;
        m = MAX(m, x);
    }
    return MIN(s, (s - m) * 2 + 1);
}
```

