class Solution {
    public int magicTower(int[] nums) {
        long sum = 0;
        for (int x : nums) {
            sum += x;
        }
        if (sum < 0) {
            return -1;
        }

        int ans = 0;
        long hp = 1;
        PriorityQueue<Integer> h = new PriorityQueue<>();
        for (int x : nums) {
            if (x < 0) {
                h.offer(x);
            }
            hp += x;
            if (hp < 1) {
                // 这意味着 x < 0，所以前面必然会把 x 入堆
                // 所以堆必然不是空的，并且堆顶 <= x
                hp -= h.poll(); // 反悔
                ans++;
            }
        }
        return ans;
    }
}
