        if (accumulate(nums.begin(), nums.end(), 0LL) < 0) {
            return -1;
        }
        int ans = 0;
        long long hp = 1;
        priority_queue<int> h; // 最大堆
        for (int x : nums) {
            if (x < 0) {
                h.push(-x);
            }
            hp += x;
            if (hp < 1) {
                // 这意味着 x < 0，所以前面必然会把 x 入堆
                // 所以堆必然不是空的，并且堆顶 >= -x
                hp += h.top(); // 反悔
                h.pop();
                ans++;
            }
        }
        return ans;
    }
};
