impl Solution {
    pub fn min_refuel_stops(target: i32, start_fuel: i32, mut stations: Vec<Vec<i32>>) -> i32 {
        stations.push(vec![target, 0]);
        let mut ans = 0;
        let mut pre_position = 0;
        let mut cur_fuel = start_fuel; // 当前油量
        let mut fuel_heap = BinaryHeap::new(); // 最大堆
