int eraseOverlapIntervals(int** intervals, int intervalsSize, int* intervalsColSize) {
    qsort(intervals, intervalsSize, sizeof(int*), cmp);
    int ans = 0;
    int pre_r = INT_MIN;
    for (int i = 0; i < intervalsSize; i++) {
        if (intervals[i][0] >= pre_r) {
            ans++;
            pre_r = intervals[i][1];
        }
    }
    return intervalsSize - ans;
}
