    for (let i = 0; i < n; i++) {
        left = Math.min(left, intervals[i][0]);
        right = Math.max(right, intervals[i][1]);
        // 下一个区间与 [left, right] 不相交
        if (i === n - 1 || intervals[i + 1][0] > right) {
            ans.push([left, right]);
            left = Infinity;
        }
    }

    return ans;
};
```

