        }

        int[] diff = new int[mx * 2 + 2];
        for (int[] p : intervals) {
            // 把区间 [p[0]*2, p[1]*2] 增加 1
            diff[p[0] * 2]++;
            diff[p[1] * 2 + 1]--;
        }

        List<int[]> ans = new ArrayList<>();
        int sumD = 0;
        int start = -1; // -1 表示尚未遇到合并后的区间左端点
        for (int i = 0; i < diff.length; i++) {
            sumD += diff[i]; // 计算 diff 的前缀和
            if (sumD > 0) {
