    public String makeSmallestPalindrome(String S) {
        var s = S.toCharArray();
        for (int i = 0, n = s.length; i < n / 2; i++) {
            char x = s[i], y = s[n - 1 - i];
            if (x > y) s[i] = y;
            else s[n - 1 - i] = x;
        }
        return new String(s);
    }
}
```

