## 写法一

```py [sol-Python3]
class Solution:
    def smallestPalindrome(self, s: str) -> str:
        n = len(s)
        t = sorted(s[:n // 2])

        ans = ''.join(t)
        if n % 2:
            ans += s[n // 2]
        return ans + ''.join(reversed(t))
```

```java [sol-Java]
class Solution {
    public String smallestPalindrome(String s) {
        int n = s.length();
        int m = n / 2;
        char[] t = s.substring(0, m).toCharArray();
        Arrays.sort(t);

        StringBuilder ans = new StringBuilder(n); // 预分配空间
        ans.append(t);
        if (n % 2 > 0) {
            ans.append(s.charAt(m));
        }
        for (int i = m - 1; i >= 0; i--) {
            ans.append(t[i]);
        }
        return ans.toString();
    }
}
```

