        int cnt[26]{};
        for (int i = 0; i < n / 2; i++) {
            cnt[s[i] - 'a']++;
        }

        string ans;
        for (int i = 0; i < 26; i++) {
            ans += string(cnt[i], 'a' + i);
        }

