impl Solution {
    pub fn max_diff(num: i32) -> i32 {
        let s = num.to_string();
        let s_bytes = s.as_bytes();

        let replace = |old: u8, new: &str| -> i32 {
            let t = s.replace(old as char, new);
            t.parse::<i32>().unwrap()
        };

        let mut mx = num;
        for &d in s_bytes {
            if d != b'9' {
                mx = replace(d, "9");
                break;
            }
        }

        let mut mn = num;
        if s_bytes[0] != b'1' {
            mn = replace(s_bytes[0], "1");
        } else {
            for &d in &s_bytes[1..] {
                if d > b'1' { // 不是 0 也不是 1
                    mn = replace(d, "0");
                    break;
                }
            }
        }

        mx - mn
    }
}
