```go [sol-Go]
func clearStars(s string) string {
	stacks := make([][]int, 26)
	for i, c := range s {
		if c != '*' {
			stacks[c-'a'] = append(stacks[c-'a'], i)
			continue
		}
		for j, st := range stacks {
			if len(st) > 0 {
				stacks[j] = st[:len(st)-1]
				break
			}
		}
	}

	idx := []int{}
	for _, p := range stacks {
		idx = append(idx, p...)
	}
	slices.Sort(idx)

	ans := make([]byte, len(idx))
	for i, j := range idx {
		ans[i] = s[j]
	}
	return string(ans)
}
