```java [sol-Java]
class Solution {
    public String clearStars(String S) {
        char[] s = S.toCharArray();
        int n = s.length;
        List<Integer>[] stacks = new ArrayList[26];
        Arrays.setAll(stacks, i -> new ArrayList<>());
        for (int i = 0; i < n; i++) {
            if (s[i] != '*') {
                stacks[s[i] - 'a'].add(i);
                continue;
            }
            for (List<Integer> st : stacks) {
                if (!st.isEmpty()) {
                    s[st.removeLast()] = '*';
                    break;
                }
            }
        }

        // 原地修改，去掉 s 中的 '*'
        int idx = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] != '*') {
                s[idx++] = s[i];
            }
        }
        return new String(s, 0, idx);
    }
}
