func clearStars(S string) string {
	s := []byte(S)
	stacks := make([][]int, 26)
	for i, c := range s {
		if c != '*' {
			stacks[c-'a'] = append(stacks[c-'a'], i)
			continue
		}
		for j, st := range stacks {
			if m := len(st); m > 0 {
				s[st[m-1]] = '*'
				stacks[j] = st[:m-1]
				break
			}
		}
	}

	ans := s[:0]
	for _, c := range s {
		if c != '*' {
			ans = append(ans, c)
		}
	}
	return string(ans)
}
