public:
    string clearStars(string s) {
        stack<int> stacks[26];
        uint32_t mask = 0;
        for (int i = 0; i < s.size(); i++) {
            if (s[i] != '*') {
                stacks[s[i] - 'a'].push(i);
                mask |= 1 << (s[i] - 'a'); // 标记第 s[i]-'a' 个栈为非空
            } else {
                int k = countr_zero(mask);
                auto& st = stacks[k];
                s[st.top()] = '*';
                st.pop();
                if (st.empty()) {
                    mask ^= 1 << k; // 标记第 k 个栈为空
                }
            }
        }

        erase(s, '*');
        return s;
    }
};
