```go [sol-Go]
func clearStars(S string) string {
	s := []byte(S)
	stacks := [26][]int{}
	mask := 0
	for i, c := range s {
		if c != '*' {
			c -= 'a'
			stacks[c] = append(stacks[c], i)
			mask |= 1 << c // 标记第 c 个栈为非空
		} else {
			k := bits.TrailingZeros(uint(mask))
			st := stacks[k]
			s[st[len(st)-1]] = '*'
			stacks[k] = st[:len(st)-1]
			if len(stacks[k]) == 0 {
				mask ^= 1 << k // 标记第 k 个栈为空
			}
		}
	}

	t := s[:0]
	for _, c := range s {
		if c != '*' {
			t = append(t, c)
		}
	}
	return string(t)
}
```

