impl Solution {
    pub fn robot_with_string(s: String) -> String {
        let n = s.len();
        // 计算后缀最小值
        let mut suf_min = vec![u8::MAX; n + 1];
        for (i, ch) in s.bytes().enumerate().rev() {
            suf_min[i] = suf_min[i + 1].min(ch);
        }

        let mut ans = Vec::with_capacity(n);
        let mut st = vec![];
