func lexicographicallySmallestArray(nums []int, limit int) []int {
	n := len(nums)
	pos := make([]int, n)
	for i := range pos {
		pos[i] = i
	}
	slices.SortFunc(pos, func(i, j int) int { return nums[i] - nums[j] })
