class Solution {
    public String lexGreaterPermutation(String s, String target) {
        char[] t = target.toCharArray();
        int n = t.length;
        int[] left = new int[26];
        for (int i = 0; i < n; i++) {
            left[s.charAt(i) - 'a']++;
            left[t[i] - 'a']--; // 消耗 s 中的一个字母 t[i]
        }

        // 从右往左尝试
        next:
        for (int i = n - 1; i >= 0; i--) {
            int b = t[i] - 'a';
            left[b]++; // 撤销消耗
            for (int c : left) {
                if (c < 0) { // [0,i-1] 无法做到全部一样
                    continue next;
                }
            }

            // 把 target[i] 增大到 j
            for (int j = b + 1; j < 26; j++) {
                if (left[j] == 0) {
                    continue;
                }

                left[j]--;
                StringBuilder ans = new StringBuilder(target.substring(0, i + 1));
                ans.setCharAt(i, (char) ('a' + j));

                for (int k = 0; k < 26; k++) {
                    ans.repeat('a' + k, left[k]);
                }
                return ans.toString();
            }
        }
        return "";
    }
}
