## 另一种写法

用一个二进制数 $\textit{mask}$ 维护 $\textit{left}$ 中的出现次数大于 $0$ 的字母集合，详见 [从集合论到位运算，常见位运算技巧分类总结！](https://leetcode.cn/circle/discuss/CaOJ45/)

```py [sol-Python3]
class Solution:
    def lexGreaterPermutation(self, s: str, target: str) -> str:
        left = Counter(s)
        for c in target:
            left[c] -= 1  # 消耗 s 中的一个字母 c

        neg = mask = 0
        for c, cnt in left.items():
            if cnt < 0:
                neg += 1  # 统计 left 中的负数个数
            elif cnt > 0:
                mask |= 1 << (ord(c) - ord('a'))

        for i in range(len(s) - 1, -1, -1):
            c = target[i]
            left[c] += 1  # 撤销消耗

            idx = ord(c) - ord('a')
            if left[c] == 0:
                neg -= 1
            elif left[c] == 1:
                mask |= 1 << idx

            # left 有负数 or 没有大于 target[i] 的字母
            if neg > 0 or mask >> (idx + 1) == 0:
                continue

            mask &= ~((1 << (idx + 1)) - 1)
            j = (mask & -mask).bit_length() - 1  # 也可以写循环找 j

            ch = ascii_lowercase[j]
            left[ch] -= 1
            ans = list(target[:i + 1])
            ans[i] = ch

            for ch in ascii_lowercase:
                ans.extend(ch * left[ch])
            return ''.join(ans)

        return ""
