```go [sol-Go]
func lexGreaterPermutation(s, target string) string {
	left := make([]int, 26)
	for i, b := range s {
		left[b-'a']++
		left[target[i]-'a']--
	}

	neg, mask := 0, 0
	for i, cnt := range left {
		if cnt < 0 {
			neg++ // 统计 left 中的负数个数
		} else if cnt > 0 {
			mask |= 1 << i
		}
	}

	for i := len(s) - 1; i >= 0; i-- {
		b := target[i] - 'a'
		left[b]++ // 撤销消耗

		if left[b] == 0 {
			neg--
		} else if left[b] == 1 {
			mask |= 1 << b
		}

		// left 有负数 or 没有大于 target[i] 的字母
		if neg > 0 || mask>>(b+1) == 0 {
			continue
		}

		// 把 target[i] 增大到 j
		mask &^= 1<<(b+1) - 1
		j := bits.TrailingZeros(uint(mask)) // 也可以写循环找 j
		left[j]--
		ans := []byte(target[:i+1])
		ans[i] = 'a' + byte(j)

		for k, c := range left {
			ch := string('a' + byte(k))
			ans = append(ans, strings.Repeat(ch, c)...)
		}
		return string(ans)
	}
	return ""
}
