        int leftMax = 0;
        for (int i = 0; i < 26; i++) {
            if (left[i] < 0) {
                neg++; // 统计 left 中的负数个数
            } else if (left[i] > 0) {
                leftMax = Math.max(leftMax, i); // 剩余可用字母的最大值
            }
        }

