    pub fn valid_palindrome(s: String) -> bool {
        let s = s.as_bytes();
        let mut i = 0;
        let mut j = s.len() - 1;
        while i < j {
            if s[i] != s[j] {
                // 删除 s[i] 或者 s[j]
                return Self::is_palindrome(&s[i + 1..=j]) || Self::is_palindrome(&s[i..j]);
            }
            i += 1;
            j -= 1;
        }
        true // s 本身就是回文串
    }
}
