```java [sol-Java]
class Solution {
    public int splitNum(int num) {
        char[] s = Integer.toString(num).toCharArray();
        Arrays.sort(s);
        int[] a = new int[2];
        for (int i = 0; i < s.length; i++) {
            a[i % 2] = a[i % 2] * 10 + s[i] - '0'; // 按照奇偶下标分组
        }
        return a[0] + a[1];
    }
}
