public:
    long long sum;

    Node(int l, int r, Node* lo = nullptr, Node* ro = nullptr, long long cnt = 0, long long sum = 0)
        : l(l), r(r), lo(lo), ro(ro), cnt(cnt), sum(sum) {}

    static Node* build(int l, int r) {
