class Node {
    private final int l;
    private final int r;
    private Node lo;
    private Node ro;
    private int cnt;
    public long sum;

    private void maintain() {
        cnt = lo.cnt + ro.cnt;
        sum = lo.sum + ro.sum;
    }

    public Node(int l, int r, Node lo, Node ro, int cnt, long sum) {
        this.l = l;
        this.r = r;
        this.lo = lo;
        this.ro = ro;
        this.cnt = cnt;
        this.sum = sum;
    }

    public Node(int l, int r) {
        this(l, r, null, null, 0, 0);
    }

    public static Node build(int l, int r) {
        Node o = new Node(l, r);
        if (l == r) {
            return o;
        }
        int mid = (l + r) / 2;
        o.lo = build(l, mid);
        o.ro = build(mid + 1, r);
        return o;
    }

    // 在线段树的位置 i 添加 val
    public Node add(int i, int val) {
        Node o = new Node(l, r, lo, ro, cnt, sum); // 复制当前节点
        if (l == r) {
            o.cnt++;
            o.sum += val;
            return o;
        }
        int mid = (l + r) / 2;
        if (i <= mid) {
            o.lo = o.lo.add(i, val);
        } else {
            o.ro = o.ro.add(i, val);
        }
        o.maintain();
        return o;
    }

    // 查询 old 和 this 对应子数组的第 k 小，有多少个数小于第 k 小，这些数的元素和是多少
    public long[] query(Node old, int k) {
        if (l == r) {
            return new long[]{l, 0, 0};
        }
        int cntL = lo.cnt - old.lo.cnt;
        if (k <= cntL) {
            return lo.query(old.lo, k);
        }
        long[] res = ro.query(old.ro, k - cntL);
        res[1] += cntL;
        res[2] += lo.sum - old.lo.sum;
        return res;
    }
}

class Solution {
    public long[] minOperations(int[] nums, int k, int[][] queries) {
        int n = nums.length;
        int[] left = new int[n];
        for (int i = 1; i < n; i++) {
            left[i] = nums[i] % k == nums[i - 1] % k ? left[i - 1] : i;
        }

        // 准备离散化
        int[] sorted = nums.clone();
        Arrays.sort(sorted);

        // 构建可持久化线段树
        Node[] t = new Node[n + 1];
        t[0] = Node.build(0, n - 1);
        for (int i = 0; i < n; i++) {
            int j = Arrays.binarySearch(sorted, nums[i]);
            t[i + 1] = t[i].add(j, nums[i]);
        }

        long[] ans = new long[queries.length];

        for (int qi = 0; qi < queries.length; qi++) {
            int[] q = queries[qi];
            int l = q[0];
            int r = q[1];
            if (left[r] > l) { // 无解
                ans[qi] = -1;
                continue;
            }

            r++; // 改成左闭右开

            // 计算区间中位数
            int sz = r - l;
            long[] res = t[r].query(t[l], sz / 2 + 1);
            long median = sorted[(int) res[0]]; // 离散化后的值 -> 原始值

            // 计算区间所有元素到中位数的距离和
            long totalSum = t[r].sum - t[l].sum;
            long cntLeft = res[1];
            long sumLeft = res[2];
            long sum = median * cntLeft - sumLeft; // 蓝色面积
            sum += totalSum - sumLeft - median * (sz - cntLeft); // 绿色面积
            ans[qi] = sum / k; // 操作次数 = 距离和 / k
        }

        return ans;
    }
}
