            long long total = t[r]->sum - t[l]->sum; // 区间元素和
            long long sum = median * cnt_left - sum_left; // 蓝色面积
            sum += total - sum_left - median * (sz - cnt_left); // 绿色面积
            ans.push_back(sum / k); // 操作次数 = 距离和 / k
        }

        // 省略 delete 线段树节点的代码
        return ans;
    }
