func minImpossibleOR(nums []int) int {
	mask := 0
	for _, x := range nums {
		if x&(x-1) == 0 { // x 是 2 的幂次
			mask |= x
		}
	}
	mask = ^mask
	return mask & -mask // lowbit
}
```

### 复杂度分析

- 时间复杂度：$O(n)$，其中 $n$ 为 $\textit{nums}$ 的长度。
- 空间复杂度：$O(1)$。仅用到若干额外变量。

