        }

        int xor_sum = reduce(nums.begin(), nums.end(), 0, bit_xor());
        // 如果 xor_sum 为 0，那么去掉 nums 的一个非零元素，就可以使 xor_sum 不为 0
        return nums.size() - (xor_sum == 0);
