        for (int x : nums) {
            mx = Math.max(mx, x);
        }

        boolean[] vis = new boolean[mx + 1];
        int ans = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (!vis[x] && x != target[i]) {
                vis[x] = true;
                ans++;
            }
        }
        return ans;
    }
}
