class Solution {
    public int countCollisions(String s) {
        s = s.replaceAll("^L+", ""); // 前缀向左的车不会发生碰撞
        s = new StringBuilder(s).reverse().toString().replaceAll("^R+", ""); // 后缀向右的车不会发生碰撞
        return (int) s.chars().filter(c -> c != 'S').count(); // 剩下非静止的车计入碰撞次数
    }
}
