        s.erase(find_if(s.rbegin(), s.rend(), [](auto c) { return c != 'R'; }).base(), s.end()); // 后缀向右的车不会发生碰撞
        return s.length() - ranges::count(s, 'S'); // 剩下非静止的车计入碰撞次数
