    while (r > l && s[r - 1] == 'R') {
        r--;
    }

    // 剩下非静止的车计入碰撞次数
    int cnt = 0; 
    for (int i = l; i < r; i++) {
        cnt += s[i] != 'S';
    }
    return cnt;
}
```

