impl Solution {
    pub fn longest_subsequence(s: String, k: i32) -> i32 {
        let n = s.len();
        let m = (32 - k.leading_zeros()) as usize; // k 的二进制长度
        if n < m {
            return n as _; // 全选
        }

        let suf_val = i32::from_str_radix(&s[n - m..], 2).unwrap();
