long long maximumOr(int* nums, int numsSize, int k) {
    // suf[i] 表示 nums[i+1] 到 nums[n-1] 的 OR
    int* suf = malloc(numsSize * sizeof(int));
    suf[numsSize - 1] = 0;
    for (int i = numsSize - 2; i >= 0; i--) {
        suf[i] = suf[i + 1] | nums[i + 1];
