var maximumOr = function(nums, k) {
    const n = nums.length;
    // suf[i] 表示 nums[i+1] 到 nums[n-1] 的 OR
    const suf = Array(n);
    suf[n - 1] = 0;
    for (let i = n - 2; i >= 0; i--) {
        suf[i] = suf[i + 1] | nums[i + 1];
    }

    // pre 表示 nums[0] 到 nums[i-1] 的 OR
    let ans = 0n, pre = 0n;
