        return reduce(nums.begin(), nums.end(), 0LL) - 1LL * ranges::min(nums) * nums.size();
    }
};
```

```c [sol-C]
#define MIN(a, b) ((b) < (a) ? (b) : (a))

int minMoves(int* nums, int numsSize) {
