func closeStrings(s, t string) bool {
    if len(s) != len(t) {
        return false
    }

    var sMask, tMask int
    var sCnt, tCnt [26]int
    for _, c := range s {
        sMask |= 1 << (c - 'a') // 记录 s 中有字符 c
        sCnt[c-'a']++
    }
    for _, c := range t {
        tMask |= 1 << (c - 'a') // 记录 t 中有字符 c
        tCnt[c-'a']++
