```py [sol-Python3]
class Solution:
    def minCost(self, nums1: List[int], nums2: List[int]) -> int:
        diff = Counter(nums1)
        diff.subtract(nums2)

        ans = 0
        for d in diff.values():
            if d % 2:
                return -1
            if d > 0:
                ans += d
        return ans // 2
```

```java [sol-Java]
class Solution {
    public int minCost(int[] nums1, int[] nums2) {
        Map<Integer, Integer> diff = new HashMap<>(); // 更快的写法见【Java 数组】
        for (int x : nums1) {
            diff.merge(x, 1, Integer::sum); // diff[x]++
        }
        for (int x : nums2) {
            diff.merge(x, -1, Integer::sum); // diff[x]--
        }

        int ans = 0;
        for (int d : diff.values()) {
            if (d % 2 != 0) {
                return -1;
            }
            if (d > 0) {
                ans += d;
            }
        }
        return ans / 2;
    }
}
```

```java [sol-Java 数组]
class Solution {
    public int minCost(int[] nums1, int[] nums2) {
        int mx = 0;
        for (int x : nums1) {
            mx = Math.max(mx, x);
        }
        for (int x : nums2) {
            mx = Math.max(mx, x);
        }

        int[] diff = new int[mx + 1];
        for (int x : nums1) {
            diff[x]++;
        }
        for (int x : nums2) {
            diff[x]--;
        }

        int ans = 0;
        for (int d : diff) {
            if (d % 2 != 0) {
                return -1;
            }
            if (d > 0) {
                ans += d;
            }
        }
        return ans / 2;
    }
}
