```cpp [sol-C++ 快速选择]
class Solution {
public:
    long long putMarbles(vector<int>& weights, int k) {
        k--; // 注意这里减一了
        if (k == 0) {
            return 0;
        }
        int n = weights.size() - 1;
        for (int i = 0; i < n; i++) {
            weights[i] += weights[i + 1];
        }
        weights.pop_back();

        long ans = 0;
        ranges::nth_element(weights, weights.begin() + k);
        for (int i = 0; i < k; i++) {
            ans -= weights[i];
        }
        ranges::nth_element(weights, weights.end() - k);
        for (int i = 0; i < k; i++) {
            ans += weights[n - 1 - i];
        }
        return ans;
    }
};
```

```go [sol-Go]
func putMarbles(weights []int, k int) (ans int64) {
	for i, w := range weights[1:] {
		weights[i] += w
	}
	weights = weights[:len(weights)-1]
	slices.Sort(weights)
	for _, w := range weights[len(weights)-k+1:] {
		ans += int64(w)
	}
	for _, w := range weights[:k-1] {
		ans -= int64(w)
	}
	return
}
```

