func numMovesStonesII(s []int) []int {
    slices.Sort(s)
    n := len(s)
    e1 := s[n-2] - s[0] - n + 2
    e2 := s[n-1] - s[1] - n + 2 // 计算空位
    maxMove := max(e1, e2)
    if e1 == 0 || e2 == 0 { // 特殊情况：没有空位
        return []int{min(2, maxMove), maxMove}
