```js [sol-JS]
var groupAnagrams = function(strs) {
    const m = new Map();
    for (const s of strs) {
        // 把 s 排序，作为哈希表的 key
        const sortedS = s.split('').sort().join('');
        if (!m.has(sortedS)) {
            m.set(sortedS, []);
        }
        // 排序后相同的字符串，保存到同一组中
        m.get(sortedS).push(s);
    }
    // 哈希表的所有 value 就是分组结果
    return Array.from(m.values());
};
