```go [sol-Go]
var powTwoSortedStrSet = map[string]bool{}

func init() {
    const maxN = 1_000_000_000
    for i := 1; i < maxN; i <<= 1 {
        s := intToSortedStr(i)
        powTwoSortedStrSet[s] = true
    }
