```py [sol-Python3]
class Solution:
    def processStr(self, s: str, k: int) -> str:
        n = len(s)
        size = [0] * n
        sz = 0
        for i, c in enumerate(s):
            if c == '*':
                sz = max(sz - 1, 0)
            elif c == '#':
                sz *= 2
            elif c != '%':  # c 是字母
                sz += 1
            size[i] = sz

        if k >= size[-1]:  # 下标越界
            return '.'

        # 迭代
        for i in range(n - 1, -1, -1):
            c = s[i]
            sz = size[i]
            if c == '#':
                if k >= sz // 2:  # k 在复制后的右半边
                    k -= sz // 2
            elif c == '%':
                k = sz - 1 - k  # 反转前的下标为 sz-1-k 的字母就是答案
            elif c != '*' and k == sz - 1:  # 找到答案
                return c
```

