- 空间复杂度：$\mathcal{O}(m)$。

## 方法二：Dijkstra

**前置知识**：[Dijkstra 算法介绍](https://leetcode.cn/problems/network-delay-time/solution/liang-chong-dijkstra-xie-fa-fu-ti-dan-py-ooe8/)。

也可以从 $0$ 出发，每次走当前能访问到的边中，边权最小的边，这类似 Dijkstra 求最短路。

本题是计算路径边权最大值，把 Dijkstra 算法中的 $+$ 改成 $\max$ 即可。

最终答案为 $\max(\textit{dis})$。

### 答疑

问：能否只用 DFS 做？每次优先访问边权小的边。

答：有反例，具体见 [视频讲解](https://www.bilibili.com/video/BV1HKcue9ETm/?t=23m53s)。

```py [sol-Python3]
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], _: int) -> int:
        if len(edges) < n - 1:
            return -1

        g = [[] for _ in range(n)]
        for x, y, w in edges:
            g[y].append((x, w))

        dis = [inf] * n
        dis[0] = 0
        h = [(0, 0)]  # (路径最大边权, 节点编号)
        while h:
            d, x = heappop(h)
            if d > dis[x]:
                continue
            for y, w in g[x]:
                new_d = max(d, w)
                if new_d < dis[y]:
                    dis[y] = new_d
                    heappush(h, (new_d, y))

        ans = max(dis)
        return -1 if ans == inf else ans
```

```java [sol-Java]
class Solution {
    public int minMaxWeight(int n, int[][] edges, int threshold) {
        if (edges.length < n - 1) {
            return -1;
        }

        List<int[]>[] g = new ArrayList[n];
        Arrays.setAll(g, i -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0], y = e[1], w = e[2];
            g[y].add(new int[]{x, w});
        }

        int[] dis = new int[n];
        Arrays.fill(dis, Integer.MAX_VALUE);
        dis[0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, 0}); // (路径最大边权, 节点编号)
        int ans = 0;
        while (!pq.isEmpty()) {
            int[] p = pq.poll();
            int d = p[0], x = p[1];
            if (d > dis[x]) {
                continue;
            }
            ans = d;
            n--;
            for (int[] e : g[x]) {
                int y = e[0];
                int newD = Math.max(d, e[1]);
                if (newD < dis[y]) {
                    dis[y] = newD;
                    pq.offer(new int[]{newD, y});
                }
            }
        }

        return n > 0 ? -1 : ans;
    }
}
```

```cpp [sol-C++]
class Solution {
public:
    int minMaxWeight(int n, vector<vector<int>>& edges, int) {
        if (edges.size() < n - 1) {
            return -1;
        }

        vector<vector<pair<int, int>>> g(n);
        for (auto& e : edges) {
            int x = e[0], y = e[1], w = e[2];
            g[y].emplace_back(x, w);
        }

        vector<int> dis(n, INT_MAX);
        dis[0] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
        pq.emplace(0, 0); // (路径最大边权, 节点编号)
        while (!pq.empty()) {
            auto [d, x] = pq.top();
            pq.pop();
            if (d > dis[x]) {
                continue;
            }
            for (auto& [y, w] : g[x]) {
                int new_d = max(d, w);
                if (new_d < dis[y]) {
                    dis[y] = new_d;
                    pq.emplace(new_d, y);
                }
            }
        }

        int ans = ranges::max(dis);
        return ans == INT_MAX ? -1 : ans;
    }
};
