int movesToChessboard(int** board, int n, int* boardColSize) {
    int* firstRow = board[0];
    int rowCnt[2] = {}, colCnt[2] = {};
    for (int i = 0; i < n; i++) {
        rowCnt[firstRow[i]]++;
        colCnt[board[i][0]]++;
    }
    // 第一行，0 和 1 的个数之差不能超过 1
    // 第一列，0 和 1 的个数之差不能超过 1
    if (abs(rowCnt[0] - rowCnt[1]) > 1 || abs(colCnt[0] - colCnt[1]) > 1) {
        return -1;
