        }
    }

    int* firstCol = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        firstCol[i] = board[i][0];
    }
    int ans = minSwap(firstRow, n, rowCnt) + minSwap(firstCol, n, colCnt);
    free(firstCol);
    return ans;
}
