            int j = belong[x];
            if (q[0] == 2) {
                if (offline_time[x] == i) { // 变回在线
                    mn[j] = min(mn[j], x);
                }
            } else if (i < offline_time[x]) { // 已经在线（写 < 或者 <= 都可以）
                ans.push_back(x);
            } else if (mn[j] != INT_MAX) {
                ans.push_back(mn[j]);
            } else {
                ans.push_back(-1);
            }
        }
        ranges::reverse(ans);
        return ans;
    }
};
```

```go [sol-Go]
func processQueries(c int, connections [][]int, queries [][]int) []int {
	g := make([][]int, c+1)
	for _, e := range connections {
		x, y := e[0], e[1]
		g[x] = append(g[x], y)
		g[y] = append(g[y], x)
	}

	belong := make([]int, c+1)
	for i := range belong {
		belong[i] = -1
	}
	cc := 0 // 连通块编号

	var dfs func(int)
	dfs = func(x int) {
		belong[x] = cc // 记录节点 x 在哪个连通块
		for _, y := range g[x] {
			if belong[y] < 0 {
				dfs(y)
			}
		}
	}
	for i := 1; i <= c; i++ {
		if belong[i] < 0 {
			dfs(i)
			cc++
		}
	}

	offlineTime := make([]int, c+1)
	for i := range offlineTime {
		offlineTime[i] = math.MaxInt
	}
	q1 := 0
	for i, q := range slices.Backward(queries) {
		if q[0] == 2 {
			offlineTime[q[1]] = i // 记录最早离线时间
		} else {
			q1++
		}
	}

	// 维护每个连通块的在线电站的最小编号
	mn := make([]int, cc)
	for i := range mn {
		mn[i] = math.MaxInt
	}
	for i := 1; i <= c; i++ {
		if offlineTime[i] == math.MaxInt { // 最终仍然在线
			j := belong[i]
			mn[j] = min(mn[j], i)
		}
	}

	ans := make([]int, q1)
	for i, q := range slices.Backward(queries) {
		x := q[1]
		j := belong[x]
		if q[0] == 2 {
			if offlineTime[x] == i { // 变回在线
				mn[j] = min(mn[j], x)
			}
		} else {
			q1--
			if i < offlineTime[x] { // 已经在线（写 < 或者 <= 都可以）
				ans[q1] = x
			} else if mn[j] != math.MaxInt {
				ans[q1] = mn[j]
			} else {
				ans[q1] = -1
			}
		}
	}
	return ans
}
```

#### 复杂度分析

- 时间复杂度：$\mathcal{O}(c+n + q)$，其中 $n$ 是 $\textit{connections}$ 的长度，$q$ 是 $\textit{queries}$ 的长度。
- 空间复杂度：$\mathcal{O}(c+n)$。返回值不计入。

