```java [sol-Java]
class Solution {
    public int minTime(String s, int[] order, int k) {
        int n = s.length();
        if ((long) n * (n + 1) / 2 < k) {
            return -1;
        }

        int[] star = new int[n]; // 避免在二分内部反复创建/初始化列表
        int left = -1;
        int right = n - 1;
        while (left + 1 < right) {
            int mid = left + (right - left) / 2;
            if (check(mid, k, order, star)) {
                right = mid;
            } else {
                left = mid;
            }
        }
        return right;
    }

    private boolean check(int m, int k, int[] order, int[] star) {
        m++;
        for (int j = 0; j < m; j++) {
            star[order[j]] = m;
        }
        int cnt = 0;
        int last = -1; // 上一个 '*' 的位置
        for (int i = 0; i < star.length; i++) {
            if (star[i] == m) { // s[i] 是 '*'
                last = i;
            }
            cnt += last + 1;
            if (cnt >= k) { // 提前退出循环
                return true;
            }
        }
        return false;
    }
}
```

