```go [sol-Go]
var dirs = []struct{ x, y int }{{0, -1}, {0, 1}, {-1, 0}, {1, 0}} // 左右上下

func latestDayToCross(m, n int, cells [][]int) int {
	// 0：水
	// 1：陆地（未被感染）
	// 2：陆地（已被感染）
	state := make([][]int8, m)
	for i := range state {
		state[i] = make([]int8, n)
	}

	// 能否从第一行到达 (r, c)
	canReachFromTop := func(r, c int) bool {
		if r == 0 { // 已经是第一行
			return true
		}
		for _, d := range dirs {
			x, y := r+d.x, c+d.y
			if 0 <= x && x < m && 0 <= y && y < n && state[x][y] == 2 {
				return true
			}
		}
		return false
	}

	// 从 (r, c) 出发，能否到达最后一行
	var dfs func(int, int) bool
	dfs = func(r, c int) bool {
		if r == m-1 {
			return true
		}
		state[r][c] = 2 // 感染
		for _, d := range dirs {
			x, y := r+d.x, c+d.y
			// 传播病毒到未被感染的陆地
			if 0 <= x && x < m && 0 <= y && y < n && state[x][y] == 1 && dfs(x, y) {
				return true
			}
		}
		return false
	}

	for day := len(cells) - 1; ; day-- {
		cell := cells[day]
		r, c := cell[0]-1, cell[1]-1 // 改成从 0 开始的下标
		state[r][c] = 1 // 未被感染的陆地
		if canReachFromTop(r, c) && dfs(r, c) {
			return day
		}
	}
}
