            int r = cell[0] - 1; // 改成从 0 开始的下标
            int c = cell[1] - 1;
            state[r][c] = 1; // 未被感染的水
            if (canReachFromLeft(r, c, state) && dfs(r, c, state)) {
                return day;
            }
        }
    }
