class Solution {
    private long ans = 0;

    public long interactionCosts(int n, int[][] edges, int[] group) {
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0];
            int y = e[1];
            g[x].add(y);
            g[y].add(x);
        }

        int mx = 0;
        for (int x : group) {
            mx = Math.max(mx, x);
