        // 找严格递减段
        while (i + 1 < ratingsSize && ratings[i] > ratings[i + 1]) {
            i++;
        }

        long long inc = top - start; // start 到 top 严格递增
        long long dec = i - top;     // top 到 i 严格递减
        ans += (inc * (inc - 1) + dec * (dec - 1)) / 2 + MAX(inc, dec);
    }
    return ans;
}
