int maxBuilding(int n, int** restrictions, int restrictionsSize, int* restrictionsColSize) {
    int m = restrictionsSize;
    if (m == 0) {
        return n - 1;
    }

    qsort(restrictions, m, sizeof(int*), cmp); // 按照 id 从小大到大排序

