impl Solution {
    pub fn max_building(n: i32, mut restrictions: Vec<Vec<i32>>) -> i32 {
        let m = restrictions.len();
        if m == 0 {
            return n - 1;
        }

        restrictions.sort_unstable_by_key(|a| a[0]); // 按照 id 从小大到大排序

