        for (int i = 0; i < n; i++) {
            auto& a = g[i];
            if (a.empty()) {
                continue;
            }
            ranges::sort(a);
            int odd = uf.odd[i];
            // 小的取负号，大的取正号
            ans -= reduce(a.begin(), a.begin() + odd, 0LL);
            ans += reduce(a.begin() + odd, a.end(), 0LL);
