    pub fn min_moves_to_capture_the_queen(a: i32, b: i32, c: i32, d: i32, e: i32, f: i32) -> i32 {
        if a == e && (c != e || (d - b) * (d - f) > 0) || // 车直接攻击到皇后（同一行）
            b == f && (d != f || (c - a) * (c - e) > 0) || // 车直接攻击到皇后（同一列）
            c + d == e + f && (a + b != e + f || (a - c) * (a - e) > 0) || // 象直接攻击到皇后
            c - d == e - f && (a - b != e - f || (a - c) * (a - e) > 0) {
            return 1;
        }
        2
    }
}
