	res1 := (a + b) * flipCost
	res2 := a*swapCost + (b-a)*flipCost
	avg := (a + b) / 2
	res3 := (avg-a)*crossCost + avg*swapCost + (a+b)%2*flipCost
	return int64(min(res1, res2, res3))
}
```

