func minCostSetTime(startAt, moveCost, pushCost, sec int) int {
	ans := math.MaxInt32
	calc := func(s string) {
		cost := pushCost * len(s)
		cur := startAt
		for _, ch := range s {
			if int(ch&15) != cur {
				cost += moveCost
				cur = int(ch & 15)
			}
		}
		if cost < ans { ans = cost }
	} 
	if sec >= 60 && sec < 6000 {
		calc(fmt.Sprintf("%d%02d", sec/60, sec%60))
