    // 把矩阵 a 顺时针旋转 90°
    vector<vector<int>> rotate(const vector<vector<int>>& a) {
        int m = a.size(), n = a[0].size();
        vector b(n, vector<int>(m));
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
