// 3195. 包含所有 1 的最小矩形面积 I
// 限定在 a 的 [l,r) 列中
func minimumArea(a [][]int, l, r int) int {
	left, right := r, 0
	top, bottom := len(a), 0
	for i, row := range a {
		for j, x := range row[l:r] {
			if x == 1 {
				left = min(left, j)
				right = max(right, j)
				top = min(top, i)
				bottom = i
			}
		}
	}
	return (right - left + 1) * (bottom - top + 1)
}

func minimumSum(grid [][]int) int {
	ans := math.MaxInt

	solve := func(a [][]int) {
		m, n := len(a), len(a[0])
		if m >= 3 {
			for i := 1; i < m; i++ {
				for j := i + 1; j < m; j++ {
					// 图片上左
					area := minimumArea(a[:i], 0, n)
					area += minimumArea(a[i:j], 0, n)
					area += minimumArea(a[j:], 0, n)
					ans = min(ans, area)
				}
			}
		}

		if m >= 2 && n >= 2 {
			for i := 1; i < m; i++ {
				for j := 1; j < n; j++ {
					// 图片上中
					area := minimumArea(a[:i], 0, n)
					area += minimumArea(a[i:], 0, j)
					area += minimumArea(a[i:], j, n)
					ans = min(ans, area)

					// 图片上右
					area = minimumArea(a[:i], 0, j)
					area += minimumArea(a[:i], j, n)
					area += minimumArea(a[i:], 0, n)
					ans = min(ans, area)
				}
			}
		}
	}

	solve(grid)
	solve(rotate(grid))
	return ans
}

// 把矩阵 a 顺时针旋转 90°
func rotate(a [][]int) [][]int {
	m, n := len(a), len(a[0])
	b := make([][]int, n)
	for i := range b {
		b[i] = make([]int, m)
	}
	for i, row := range a {
		for j, x := range row {
			b[j][m-1-i] = x
		}
	}
	return b
}
