func constructGridLayout(n int, edges [][]int) [][]int {
    g := make([][]int, n)
    for _, e := range edges {
        x, y := e[0], e[1]
        g[x] = append(g[x], y)
        g[y] = append(g[y], x)
    }

    // 每种度数选一个点
    degToNode := [5]int{-1, -1, -1, -1, -1}
    for x, to := range g {
        degToNode[len(to)] = x
    }

    var row []int
    if degToNode[1] != -1 {
        // 答案只有一列
        row = []int{degToNode[1]}
    } else if degToNode[4] == -1 {
        // 答案只有两列
        x := degToNode[2]
        for _, y := range g[x] {
            if len(g[y]) == 2 {
                row = []int{x, y}
                break
            }
        }
    } else {
        // 答案至少有三列
        // 寻找度数为 2333...32 的序列作为第一排
        x := degToNode[2]
        row = []int{x}
        pre := x
        x = g[x][0]
        for len(g[x]) == 3 {
            row = append(row, x)
            for _, y := range g[x] {
                if y != pre && len(g[y]) < 4 {
                    pre = x
                    x = y
                    break
                }
            }
        }
        row = append(row, x) // x 的度数是 2
    }

    k := len(row)
    ans := make([][]int, n/k)
    ans[0] = row
    vis := make([]bool, n)
    for _, x := range row {
        vis[x] = true
    }
    for i := 1; i < len(ans); i++ {
        ans[i] = make([]int, k)
        for j, x := range ans[i-1] {
            for _, y := range g[x] {
                // x 上左右的邻居都访问过了，没访问过的邻居只会在 x 下面
                if !vis[y] {
                    vis[y] = true
                    ans[i][j] = y
                    break
                }
            }
        }
    }
    return ans
}
```

## 写法二：合三为一

上文的三种情况，可以统一起来：

1. 首先找到一个度数最小的点 $x$。
2. 找 $x$ 的度数最小的邻居 $y$。
3. 找 $y$ 的度数最小的邻居 $z$，且 $z$ 之前没有访问过。（或者判断 $z\ne x$ 也可以，但是代码要更长一些。）
4. 依此类推，直到找到一个点，度数和起点是一样的。

```py [sol-Python3]
class Solution:
    def constructGridLayout(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        g = [[] for _ in range(n)]
        for x, y in edges:
            g[x].append(y)
            g[y].append(x)

        # 找一个度数最小的点
        x = 0
        for i, to in enumerate(g):
            if len(to) < len(g[x]):
                x = i

        row = [x]
        vis = [False] * n
        vis[x] = True
        deg_st = len(g[x])  # 起点的度数
        while True:  # 注意题目保证 n >= 2，可以至少循环一次
            nxt = -1
            for y in g[x]:
                if not vis[y] and (nxt < 0 or len(g[y]) < len(g[nxt])):
                    nxt = y
            x = nxt
            row.append(x)
            vis[x] = True
            if len(g[x]) == deg_st:
                break

        ans = [[] for _ in range(n // len(row))]
        ans[0] = row
        for i in range(1, len(ans)):
            for x in ans[i - 1]:
                for y in g[x]:
                    # x 上左右的邻居都访问过了，没访问过的邻居只会在 x 下面
                    if not vis[y]:
                        vis[y] = True
                        ans[i].append(y)
                        break
        return ans
```

