        // 情况 4c：A 左侧有奇数个人，且 B 与 A' 相邻
        if (first % 2 == 0 && first + second == n) {
            // 一回合后，转化为情况 4a
            res++;
        }

        // 情况 4a：A 左侧有偶数个人
        // 情况 4b：A 左侧有奇数个人，且 B 与 A' 不相邻
