    vector<vector<int>> restoreMatrix(vector<int> &rowSum, vector<int> &colSum) {
        int m = rowSum.size(), n = colSum.size();
        vector<vector<int>> mat(m, vector<int>(n));
        for (int i = 0, j = 0; i < m && j < n; ) {
            int rs = rowSum[i], cs = colSum[j];
            if (rs < cs) { // 去掉第 i 行，往下走
                colSum[j] -= rs;
                mat[i++][j] = rs;
            } else { // 去掉第 j 列，往右走
                rowSum[i] -= cs;
                mat[i][j++] = cs;
            }
        }
        return mat;
    }
};
```

```go [sol2-Go]
func restoreMatrix(rowSum, colSum []int) [][]int {
    m, n := len(rowSum), len(colSum)
    mat := make([][]int, m)
    for i := range mat {
        mat[i] = make([]int, n)
    }
    for i, j := 0, 0; i < m && j < n; {
        rs, cs := rowSum[i], colSum[j]
        if rs < cs {
            mat[i][j] = rs // 去掉第 i 行
            colSum[j] -= rs
            i++ // 往下走
        } else {
            mat[i][j] = cs // 去掉第 j 列
            rowSum[i] -= cs
            j++ // 往右走
        }
    }
    return mat
}
```

### 复杂度分析

- 时间复杂度：$O(mn)$，其中 $m$ 为矩阵行数，即 $\textit{rowSum}$ 的长度；$n$ 为矩阵列数，即 $\textit{colSum}$ 的长度。如果忽略创建二维数组的时间，时间复杂度为 $O(m+n)$。
- 空间复杂度：$O(1)$。返回值不计入。

