**核心思路**：构造一个 $k\times 2$ 或 $2\times k$ 的全为 $\texttt{.}$ 的区域，这个区域从左上角移动到右下角，恰好有 $k$ 条路径。

[本题视频讲解](https://www.bilibili.com/video/BV1YsNg6eEr9/)，欢迎点赞关注~

```py [sol-Python3]
class Solution:
    def createGrid(self, m: int, n: int, k: int) -> list[str]:
        # 特判
        if k == 4 and m == 3 and n == 3:
            return ["..#", "...", "#.."]

        if m == 1 or n == 1:
            # 一行或一列，只能有一种方案
            if k > 1:
                return []
            return ['.' * n] * m

        # 至少要有 k 行或 k 列（特殊情况上面已判断）
        if m < k and n < k:
            return []

        # 初始全为 '#'（第一列全为 '.'）
        a = [['.'] + ['#'] * (n - 1) for _ in range(m)]
        a[-1] = '.' * n  # 最后一行全为 '.'
        if n >= k:  # 至少有 k 列
            # 倒数第二行开头 k 个 '.'
            for j in range(1, k):
                a[-2][j] = '.'
        else:  # 至少有 k 行
            # 第二列末尾 k 个 '.'
            for i in range(m - k, m - 1):
                a[i][1] = '.'
        return [''.join(row) for row in a]
```

```java [sol-Java]
class Solution {
    public String[] createGrid(int m, int n, int k) {
        // 特判
        if (k == 4 && m == 3 && n == 3) {
            return new String[]{"..#", "...", "#.."};
        }

        if (m == 1 || n == 1) {
            // 一行或一列，只能有一种方案
            if (k > 1) {
                return new String[0];
            }
            // 全为 '.'
            String[] ans = new String[m];
            Arrays.fill(ans, ".".repeat(n));
            return ans;
        }

        // 至少要有 k 行或 k 列（特殊情况上面已判断）
        if (m < k && n < k) {
            return new String[0];
        }

        // 初始全为 '#'
        char[][] a = new char[m][n];
        for (char[] row : a) {
            Arrays.fill(row, '#');
            row[0] = '.'; // 第一列全为 '.'
        }
        Arrays.fill(a[m - 1], '.'); // 最后一行全为 '.'
        if (n >= k) { // 至少有 k 列
            // 倒数第二行开头 k 个 '.'
            for (int j = 1; j < k; j++) {
                a[m - 2][j] = '.';
            }
        } else { // 至少有 k 行
            // 第二列末尾 k 个 '.'
            for (int i = m - k; i < m - 1; i++) {
                a[i][1] = '.';
            }
        }

        String[] ans = new String[m];
        for (int i = 0; i < m; i++) {
            ans[i] = new String(a[i]);
        }
        return ans;
    }
}
