```go [sol-Go]
func createGrid(m, n, k int) []string {
	// 特判
	if k == 4 && m == 3 && n == 3 {
		return []string{"..#", "...", "#.."}
	}

	if m == 1 || n == 1 {
		// 一行或一列，只能有一种方案
		if k > 1 {
			return nil
		}
		// 全为 '.'
		ans := make([]string, m)
		row := strings.Repeat(".", n)
		for i := range ans {
			ans[i] = row
		}
		return ans
	}

	// 至少要有 k 行或 k 列（特殊情况上面已判断）
	if m < k && n < k {
		return nil
	}

	// 初始全为 '#'
	a := make([][]byte, m)
	for i := range m - 1 {
		a[i] = bytes.Repeat([]byte{'#'}, n)
		a[i][0] = '.' // 第一列全为 '.'
	}
	a[m-1] = bytes.Repeat([]byte{'.'}, n) // 最后一行全为 '.'
	if n >= k { // 至少有 k 列 
		// 倒数第二行开头 k 个 '.'
		for j := 1; j < k; j++ {
			a[m-2][j] = '.'
		}
	} else { // 至少有 k 行
		// 第二列末尾 k 个 '.'
		for _, row := range a[m-k : m-1] {
			row[1] = '.'
		}
	}

	ans := make([]string, m)
	for i, row := range a {
		ans[i] = string(row)
	}
	return ans
}
