func minSwaps(nums []int) int {
	pos1 := []int{} // 车（奇数）的下标
	for i, x := range nums {
		if x%2 != 0 {
			pos1 = append(pos1, i)
		}
	}

	n := len(nums)
	m := len(pos1)

	// start=0 表示车去偶数下标，start=1 表示车去奇数下标
	calc := func(start int) (res int) {
		if (n-start+1)/2 != m {
			return math.MaxInt
		}
		for i, j := range pos1 {
			res += abs(i*2 + start - j)
		}
		return
	}
	ans := min(calc(0), calc(1))
	if ans == math.MaxInt {
		return -1
	}
	return ans
}

func abs(x int) int { if x < 0 { return -x }; return x }
