```go
func mergeTriplets(a [][]int, t []int) bool {
	found := [3]bool{}
	for _, p := range a {
		if p[0] <= t[0] && p[1] <= t[1] && p[2] <= t[2] {
			found[0] = found[0] || p[0] == t[0]
			found[1] = found[1] || p[1] == t[1]
			found[2] = found[2] || p[2] == t[2]
		}
	}
	return found[0] && found[1] && found[2]
}
