```go [sol-Go]
func maximumSetSize(nums1, nums2 []int) int {
	set1 := map[int]bool{}
	for _, x := range nums1 {
		set1[x] = true
	}
	all := len(set1)
	set2 := map[int]bool{}
	for _, x := range nums2 {
