        f(node->next, i + 1);
        while (!st.empty() && st.top() <= node->val)
            st.pop(); // 弹出无用数据
        if (!st.empty())
            ans[i] = st.top(); // 栈顶就是第 i 个节点的下一个更大元素
        st.push(node->val);
    }

