    prev, next       *Node
}

type LFUCache struct {
    capacity    int
    minFreq     int
    keyToNode   map[int]*Node
    freqToDummy map[int]*Node
}

func Constructor(capacity int) LFUCache {
    return LFUCache{
        capacity:    capacity,
        keyToNode:   map[int]*Node{},
        freqToDummy: map[int]*Node{},
    }
}

// 删除一个节点（抽出一本书）
func (c *LFUCache) remove(x *Node) {
    x.prev.next = x.next
    x.next.prev = x.prev
}

// 在链表头添加一个节点（把一本书放到最上面）
func (c *LFUCache) pushFront(freq int, x *Node) {
    dummy := c.freqToDummy[freq]
    if dummy == nil { // 这摞书是空的
        // 创建一个新的双向链表
        dummy = &Node{}
        dummy.prev = dummy
        dummy.next = dummy
        c.freqToDummy[freq] = dummy
    }
    x.prev = dummy
    x.next = dummy.next
    x.prev.next = x
    x.next.prev = x
}

func (c *LFUCache) getNode(key int) *Node {
    node := c.keyToNode[key]
    if node == nil { // 没有这本书
        return nil
    }
    c.remove(node) // 把这本书抽出来
    dummy := c.freqToDummy[node.freq]
    if dummy.prev == dummy { // 抽出来后，这摞书是空的
        delete(c.freqToDummy, node.freq) // 移除空链表
        if c.minFreq == node.freq { // 这摞书是最左边的
            c.minFreq++
        }
    }
    node.freq++ // 看书次数 +1
    c.pushFront(node.freq, node) // 放在右边这摞书的最上面
    return node
}

func (c *LFUCache) Get(key int) int {
    if node := c.getNode(key); node != nil { // 有这本书
        return node.value
    }
    return -1 // 没有这本书
}

func (c *LFUCache) Put(key, value int) {
    if node := c.getNode(key); node != nil { // 有这本书
        node.value = value // 更新 value
        return
    }
    if len(c.keyToNode) == c.capacity { // 书太多了
        dummy := c.freqToDummy[c.minFreq] // 最左边那摞书
        backNode := dummy.prev // 最左边那摞书的最下面的书
        delete(c.keyToNode, backNode.key)
        c.remove(backNode) // 移除
        if dummy.prev == dummy { // 这摞书是空的
            delete(c.freqToDummy, c.minFreq) // 移除空链表
        }
    }
    node := &Node{key: key, value: value, freq: 1} // 新书
    c.keyToNode[key] = node
    c.pushFront(1, node) // 放在「看过 1 次」的最上面
    c.minFreq = 1
