// 为方便读者理解核心逻辑，该写法没有删除空的 list
struct Entry {
    int key, value, freq; // freq 表示这本书被看的次数
};

class LFUCache {
private:
    int capacity;
    int min_freq;
    unordered_map<int, list<Entry>::iterator> key_to_iter;
    unordered_map<int, list<Entry>> freq_to_list;

    void move(list<Entry>::iterator it) {
        Entry e = *it;
        freq_to_list[e.freq].erase(it); // 把这本书抽出来
        if (freq_to_list[min_freq].empty()) { // 最左边那摞书是空的
            min_freq++;
        }
        e.freq++; // 看书次数 +1
        freq_to_list[e.freq].emplace_front(e); // 放在右边这摞书的最上面
        key_to_iter[e.key] = freq_to_list[e.freq].begin(); // 记录位置，这样可以 O(1) 从 list 中删除（把书抽出来）
    }

public:
    LFUCache(int capacity) : capacity(capacity) {}

    int get(int key) {
        auto it = key_to_iter.find(key);
        if (it == key_to_iter.end()) { // 没有这本书
            return -1;
        }
        int value = it->second->value;
        move(it->second);
        return value;
    }

    void put(int key, int value) {
        auto it = key_to_iter.find(key);
        if (it != key_to_iter.end()) { // 有这本书
            it->second->value = value; // 更新 value
            move(it->second);
            return;
        }
        if (key_to_iter.size() == capacity) { // 书太多了
            // 移除最左边那摞书的最下面的书
            auto& lst = freq_to_list[min_freq];
            key_to_iter.erase(lst.back().key);
            lst.pop_back();
        }
        freq_to_list[1].emplace_front(key, value, 1); // 把新书放在「看过 1 次」的最上面
        key_to_iter[key] = freq_to_list[1].begin();
        min_freq = 1;
    }
};
```

```go [sol-Go]
type entry struct {
    key, value, freq int // freq 表示这本书被看的次数
}

type LFUCache struct {
    capacity   int
    minFreq    int
    keyToNode  map[int]*list.Element
    freqToList map[int]*list.List
}

func Constructor(capacity int) LFUCache {
    return LFUCache{
        capacity:   capacity,
        keyToNode:  map[int]*list.Element{},
        freqToList: map[int]*list.List{},
    }
}

func (c *LFUCache) pushFront(e *entry) {
    if _, ok := c.freqToList[e.freq]; !ok {
        c.freqToList[e.freq] = list.New() // 双向链表
    }
    c.keyToNode[e.key] = c.freqToList[e.freq].PushFront(e)
}

func (c *LFUCache) getEntry(key int) *entry {
    node := c.keyToNode[key]
    if node == nil { // 没有这本书
        return nil
    }
    e := node.Value.(*entry)
    lst := c.freqToList[e.freq]
    lst.Remove(node) // 把这本书抽出来
    if lst.Len() == 0 { // 抽出来后，这摞书是空的
        delete(c.freqToList, e.freq) // 移除空链表
        if c.minFreq == e.freq { // 这摞书是最左边的
            c.minFreq++
        }
    }
    e.freq++ // 看书次数 +1
    c.pushFront(e) // 放在右边这摞书的最上面
    return e
}

func (c *LFUCache) Get(key int) int {
    if e := c.getEntry(key); e != nil { // 有这本书
        return e.value
    }
    return -1 // 没有这本书
}

func (c *LFUCache) Put(key, value int) {
    if e := c.getEntry(key); e != nil { // 有这本书
        e.value = value // 更新 value
        return
    }
    if len(c.keyToNode) == c.capacity { // 书太多了
        lst := c.freqToList[c.minFreq] // 最左边那摞书
        k := lst.Remove(lst.Back()).(*entry).key // 移除最左边那摞书的最下面的书
        delete(c.keyToNode, k)
        if lst.Len() == 0 { // 这摞书是空的
            delete(c.freqToList, c.minFreq) // 移除空链表
        }
    }
    c.pushFront(&entry{key, value, 1}) // 新书放在「看过 1 次」的最上面
    c.minFreq = 1
}
```

