            pre.Right = nil // 注：如果调用完 inorderTraversal 不再使用这棵二叉树，这行代码可以去掉
        }

        // root 的左子树访问完毕
        ans = append(ans, root.Val) // 记录当前节点的值
        root = root.Right // 如果有右子树就访问右子树，没有就顺着线索回到指向的节点
    }
    return
}
