        if (node === null) {
            return;
        }
        cnt++;
        if (node.left === null && node.right === null) { // node 是叶子
            ans = Math.min(ans, cnt);
            return;
        }
        dfs(node.left, cnt);
        dfs(node.right, cnt);
    }
    dfs(root, 0);
    return root ? ans : 0;
};
```

