## 方法一：BFS

**前置题目**：[102. 二叉树的层序遍历](https://leetcode.cn/problems/binary-tree-level-order-traversal/)，[视频讲解【基础算法精讲 13】](https://www.bilibili.com/video/BV1hG4y1277i/)。

套用 102 题的 BFS 模板，把每一层的最后一个节点值保存到答案中。

```py [sol-Python3]
class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if root is None:
            return []
        ans = []
        cur = [root]
        while cur:
            ans.append(cur[-1].val)
            nxt = []
            for node in cur:
                if node.left:  nxt.append(node.left)
                if node.right: nxt.append(node.right)
            cur = nxt
        return ans
```

```java [sol-Java]
class Solution {
    public List<Integer> rightSideView(TreeNode root) {
        if (root == null) {
            return List.of();
        }
        List<Integer> ans = new ArrayList<>();
        List<TreeNode> cur = List.of(root);
        while (!cur.isEmpty()) {
            ans.add(cur.getLast().val);
            List<TreeNode> nxt = new ArrayList<>();
            for (TreeNode node : cur) {
                if (node.left != null)  nxt.add(node.left);
                if (node.right != null) nxt.add(node.right);
            }
            cur = nxt;
        }
        return ans;
    }
}
```

```cpp [sol-C++]
class Solution {
public:
    vector<int> rightSideView(TreeNode* root) {
        if (root == nullptr) {
            return {};
        }
        vector<int> ans;
        vector<TreeNode*> cur = {root};
        while (cur.size()) {
            ans.push_back(cur.back()->val);
            vector<TreeNode*> nxt;
            for (auto node : cur) {
                if (node->left)  nxt.push_back(node->left);
                if (node->right) nxt.push_back(node->right);
            }
            cur = move(nxt);
        }
        return ans;
    }
};
```

```go [sol-Go]
