        int leftH = dfs(node.left, cnt);
        int rightH = dfs(node.right, cnt);
        if (leftH == -2 || leftH != rightH) {
            return -2; // 不合法
        }
        cnt[leftH + 1]++;
        return leftH + 1;
    }
}
