        }
        let x = root.as_ref()?;
        let left = Self::lowest_common_ancestor(x.borrow_mut().left.take(), p.clone(), q.clone());
        let right = Self::lowest_common_ancestor(x.borrow_mut().right.take(), p, q);
        if left.is_some() && right.is_some() { // 左右都找到
            return root; // 当前节点是最近公共祖先
        }
        // 如果只有左子树找到，就返回左子树的返回值
        // 如果只有右子树找到，就返回右子树的返回值
        // 如果左右子树都没有找到，就返回 None（注意此时 right = None）
        if left.is_some() { left } else { right }
    }
}
```

#### 复杂度分析

- 时间复杂度：$\mathcal{O}(n)$，其中 $n$ 为二叉树的节点个数。
- 空间复杂度：$\mathcal{O}(n)$。最坏情况下，二叉树是一条链，因此递归需要 $\mathcal{O}(n)$ 的栈空间。

