func getDirections(root *TreeNode, startValue, destValue int) string {
	path := []byte{}
	// dfs 返回是否找到了 target
	var dfs func(*TreeNode, int) bool
	dfs = func(node *TreeNode, target int) bool {
		if node == nil {
			return false
		}

		// 找到 target
		if node.Val == target {
			return true
		}

		// 往左找 target
		path = append(path, 'L')
		if dfs(node.Left, target) {
			return true
		}

		// 往右找 target
		path[len(path)-1] = 'R' // 直接覆盖，无需恢复现场
		if dfs(node.Right, target) {
			return true
		}

		path = path[:len(path)-1] // 恢复现场
		return false
	}

	dfs(root, startValue)
	pathToStart := path

	path = []byte{}
	dfs(root, destValue)
	pathToDest := path

