                return -1; // 题目保证节点值非负，用 -1 表示没有找到
            }
            int left_res = dfs(node->left);
            if (left_res != -1) { // 答案在左子树中
                return left_res;
            }
            if (--k == 0) { // 答案就是当前节点
                return node->val;
            }
            return dfs(node->right); // 右子树会返回答案或者 -1
        };
        return dfs(root);
    }
};
