    pub fn kth_smallest(root: Option<Rc<RefCell<TreeNode>>>, mut k: i32) -> i32 {
        fn dfs(node: &Option<Rc<RefCell<TreeNode>>>, k: &mut i32) -> i32 {
            if let Some(node) = node {
                let node = node.borrow();
                let left_res = dfs(&node.left, k);
