    if (x <= l.max || x >= r.min) {
        return (Pair) {LLONG_MIN, LLONG_MAX};
    }
    return (Pair) {MIN(l.min, x), MAX(r.max, x)};
}

bool isValidBST(struct TreeNode* root) {
