```go
const mx int = 5e4 + 1

func canMerge(trees []*TreeNode) *TreeNode {
    isSub := [mx]bool{}      // 对于根节点，需要知道其是否为另一颗二叉搜索树的子节点
    roots := [mx]*TreeNode{} // 对于子节点，我们需要知道其数值所对应的二叉搜索树的根节点是哪个
    for _, rt := range trees {
        if rt.Left != nil {
            if isSub[rt.Left.Val] { // 由于二叉搜索树上不能有两个值相同的节点，所以 trees 中也不能有两个值相同的子节点
                return nil
            }
            isSub[rt.Left.Val] = true
        }
        if rt.Right != nil {
            if isSub[rt.Right.Val] {
                return nil
            }
            isSub[rt.Right.Val] = true
        }
        roots[rt.Val] = rt
    }

    var root *TreeNode
    for _, rt := range trees {
        if !isSub[rt.Val] { // 根节点不应是另一颗二叉搜索树的子节点，否则二叉搜索树上会出现两个值相同的节点
            if root != nil { // 根节点应只有一个，否则会构成森林
                return nil
            }
            root = rt
        }
    }
    if root == nil { // 未找到根节点
        return nil
    }

    cnt := 0
    // 在构建二叉搜索树的同时判断是否合法
    var build func(*TreeNode, int, int) *TreeNode
    build = func(node *TreeNode, l, r int) *TreeNode {
        cnt++
        if node.Left != nil {
            if node.Left.Val <= l {
                return nil
            }
            if lo := roots[node.Left.Val]; lo != nil {
                node.Left = build(lo, l, node.Val)
                if node.Left == nil {
                    return nil
                }
            }
        }
        if node.Right != nil {
            if node.Right.Val >= r {
                return nil
            }
            if ro := roots[node.Right.Val]; ro != nil {
                node.Right = build(ro, node.Val, r)
                if node.Right == nil {
                    return nil
                }
            }
        }
        return node
    }
    root = build(root, 0, mx)
    if cnt == len(trees) { // 所有 trees[i] 均参与构建二叉搜索树
        return root
    }
    return nil
}
```

示例 1 $\textit{nums}=[-10,-3,0,5,9]$，我们从数组正中间的数 $\textit{nums}[2]=0$ 开始，把数组一分为二，得到两个小数组：

- 左：$[-10,-3]$。
- 右：$[5,9]$。

答案由三部分组成：

- 根节点：节点值为 $\textit{nums}[2]=0$。
- 把 $\textit{nums}[2]$ 左边的 $[-10,-3]$ 转换成一棵平衡二叉搜索树，作为答案的左儿子。这是一个和原问题相似的子问题，可以递归解决。
- 把 $\textit{nums}[2]$ 右边的 $[5,9]$ 转换成一棵平衡二叉搜索树，作为答案的右儿子。这是一个和原问题相似的子问题，可以递归解决。

递归边界：如果数组长度等于 $0$，返回空节点。

晕递归的同学，可以看视频讲解[【基础算法精讲 09】](https://www.bilibili.com/video/BV1UD4y1Y769/)，带你理解递归的本质。

⚠**注意**：答案可能不是唯一的。如果 $n$ 是偶数，我们可以取数组正中间左边那个数作为根节点的值，也可以取数组正中间右边那个数作为根节点的值。下面代码取的是正中间右边那个数，即下标为 $\dfrac{n}{2}$ 的数（当 $n$ 是偶数时）。

```py [sol-Python3]
class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        if not nums:
            return None
        m = len(nums) // 2
        left = self.sortedArrayToBST(nums[:m])
        right = self.sortedArrayToBST(nums[m + 1:])
        return TreeNode(nums[m], left, right)
```

```py [sol-Python3 写法二]
class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        # 把 nums[left:right] 转成平衡二叉搜索树
        def dfs(left: int, right: int) -> Optional[TreeNode]:
            if left == right:
                return None
            m = (left + right) // 2
