        leftSize := index[preorder[preL]] - inL // 左子树的大小
        left := dfs(preL+1, preL+1+leftSize, inL)
        right := dfs(preL+1+leftSize, preR, inL+1+leftSize)
        return &TreeNode{preorder[preL], left, right}
    }
    return dfs(0, n, 0) // 左闭右开区间
}
