impl Solution {
    pub fn level_order(root: Option<Rc<RefCell<TreeNode>>>) -> Vec<Vec<i32>> {
        let mut ans = vec![];
        let mut cur = vec![];
        if let Some(x) = root {
            cur.push(x);
        }
        while !cur.is_empty() {
            let mut nxt = vec![];
            let mut vals = Vec::with_capacity(cur.len()); // 预分配空间
            for node in cur {
                let mut x = node.borrow_mut();
                vals.push(x.val);
                if let Some(left) = x.left.take() {
                    nxt.push(left);
                }
                if let Some(right) = x.right.take() {
                    nxt.push(right);
                }
            }
            cur = nxt;
            ans.push(vals);
        }
        ans
    }
}
