use std::rc::Rc;
use std::cell::RefCell;

impl Solution {
    pub fn kth_largest_level_sum(root: Option<Rc<RefCell<TreeNode>>>, k: i32) -> i64 {
        let mut a = Vec::new();
        let mut cur = vec![root.unwrap()];
        while !cur.is_empty() {
            let mut sum = 0i64;
            let mut nxt = Vec::new();
            for node in cur {
                let mut x = node.borrow_mut();
                sum += x.val as i64;
                if let Some(left) = x.left.take() {
                    nxt.push(left);
                }
                if let Some(right) = x.right.take() {
                    nxt.push(right);
                }
            }
            cur = nxt;
            a.push(sum);
        }
        let k = k as usize;
        if k > a.len() {
            return -1;
        }
        a.sort_unstable();
        a[a.len() - k]
    }
}
