func verticalTraversal(root *TreeNode) [][]int {
    type pair struct{ row, val int }
    var left, right [][]pair
    var dfs func(*TreeNode, int, int)
    dfs = func(node *TreeNode, row, col int) {
        if node == nil {
            return
