## 写法二

在第一次 DFS 中，可以顺带求出每个节点的深度，保存到数组 $\textit{depth}$ 中。这样第二次 DFS 可以用简单的循环代替。

```py [sol-Python3]
class Solution:
    def weightedSum(self, parent: list[int], nums: list[int]) -> int:
        n = len(parent)
        g = [[] for _ in range(n)]
        for i in range(1, n):
            g[parent[i]].append(i)

        depth = [0] * n
        def dfs(x: int) -> None:
            for y in g[x]:
                depth[y] = depth[x] + 1
                dfs(y)
        dfs(0)

        h = max(depth) + 1
        return sum(x * (h - d) for x, d in zip(nums, depth))
```

```java [sol-Java]
class Solution {
    public long weightedSum(int[] parent, int[] nums) {
        int n = parent.length;
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int i = 1; i < n; i++) {
            g[parent[i]].add(i);
        }

        int[] depth = new int[n];
        int h = dfs(0, g, depth);

        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans += (long) nums[i] * (h - depth[i]);
        }
        return ans;
    }

    private int dfs(int x, List<Integer>[] g, int[] depth) {
        int h = 0;
        for (int y : g[x]) {
            depth[y] = depth[x] + 1;
            h = Math.max(h, dfs(y, g, depth));
        }
        return h + 1;
    }
}
