        ans = Math.max(ans, pathSum); // 更新答案的最大值
        for (int y : g[x]) { // 遍历 x 的儿子 y（如果没有儿子就不会进入循环）
            dfs(g, informTime, y, pathSum); // 继续递归
        }
    }
}
