class Solution {
public:
    int numOfMinutes(int n, int _, vector<int>& manager, vector<int>& informTime) {
        vector<int> memo(n, -1); // -1 表示还没有计算过
        auto dfs = [&](this auto&& dfs, int x) -> int {
            if (manager[x] < 0) {
                return informTime[x];
            }
            int& res = memo[x]; // 注意这里是引用
            if (res >= 0) {
                return res; // 之前计算过了
            }
            return res = dfs(manager[x]) + informTime[x];
        };
        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans = max(ans, dfs(i));
        }
        return ans;
    }
};
