func frogPosition(n int, edges [][]int, t int, target int) float64 {
    g := make([][]int, n+1)
    g[1] = []int{0} // 减少额外判断的小技巧
    for _, e := range edges {
        x, y := e[0], e[1]
        g[x] = append(g[x], y)
        g[y] = append(g[y], x) // 建树
    }

    var dfs func(int, int, int) int
    dfs = func(x, fa, leftT int) int {
        if leftT == 0 {
            if x == target { // 恰好到达
                return 1
            }
            return 0
        }
        if x == target {
            if len(g[x]) == 1 { // target 是叶子，停在原地
                return 1
            }
            return 0
        }
        for _, y := range g[x] { // 遍历 x 的儿子 y
            if y != fa { // y 不能是父节点
                prod := dfs(y, x, leftT-1) // 寻找 target
                if prod != 0 {
                    return prod * (len(g[x]) - 1) // 乘上儿子个数，并直接返回
                }
            }
        }
        return 0 // 未找到 target
    }

    prod := dfs(1, 0, t)
    if prod == 0 { // t 秒后不在 target
        return 0
    }
    return 1 / float64(prod)
}
