class Solution {
public:
    vector<int> maxTargetNodes(vector<vector<int>>& edges1, vector<vector<int>>& edges2) {
        auto count = [](vector<vector<int>>& edges) {
            vector<vector<int>> g(edges.size() + 1);
            for (auto& e : edges) {
                int x = e[0], y = e[1];
                g[x].push_back(y);
                g[y].push_back(x);
            }

            array<int, 2> cnt{};
