                cnt[d]++;
                for (int y : g[x]) {
                    if (y != fa) {
                        dfs(y, x, d ^ 1);
                    }
                }
            };
            dfs(0, -1, 0);
            return pair(g, cnt);
        };

        auto [_, cnt2] = count(edges2);
        int max2 = max(cnt2[0], cnt2[1]);

        auto [g, cnt1] = count(edges1);
        vector<int> ans(g.size(), max2);
        auto dfs = [&](this auto&& dfs, int x, int fa, int d) -> void {
            ans[x] += cnt1[d];
            for (int y : g[x]) {
                if (y != fa) {
                    dfs(y, x, d ^ 1);
                }
            }
        };
        dfs(0, -1, 0);
        return ans;
    }
};
