			if y != fa {
				dfs(y, x, d^1)
			}
		}
	}
	dfs(0, -1, 0)
	return
}

func maxTargetNodes(edges1, edges2 [][]int) []int {
	_, cnt2 := count(edges2)
	max2 := max(cnt2[0], cnt2[1])

	g, cnt1 := count(edges1)
