            max_s = cnt = 0
            for y in g[x]:
                if y == fa:
                    continue
                mx = dfs(y, x)
                if mx > max_s:
                    max_s = mx
                    cnt = 1
                elif mx == max_s:
                    cnt += 1

            nonlocal ans
            ans += len(g[x]) - 1 - cnt
