func collectTheCoins(coins []int, edges [][]int) int {
	n := len(coins)
	g := make([][]int, n)
	deg := make([]int, n)
	for _, e := range edges {
		x, y := e[0], e[1]
		g[x] = append(g[x], y)
		g[y] = append(g[y], x) // 建图
		deg[x]++
		deg[y]++ // 统计每个节点的度数（邻居个数）
	}

	leftEdges := n - 1 // 剩余边数
	// 拓扑排序，去掉没有金币的子树
	q := []int{}
	for i, d := range deg {
		if d == 1 && coins[i] == 0 { // 没有金币的叶子
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		x := q[len(q)-1]
		q = q[:len(q)-1]
		leftEdges-- // 删除节点 x 到其父节点的边
		for _, y := range g[x] {
			deg[y]--
			if deg[y] == 1 && coins[y] == 0 { // 没有金币的叶子
				q = append(q, y)
			}
		}
	}

	// 再次拓扑排序
	for i, d := range deg {
		if d == 1 && coins[i] > 0 { // 有金币的叶子（判断 coins[i] 是避免把没有金币的叶子也算进来）
			q = append(q, i)
		}
	}
	leftEdges -= len(q) // 删除所有叶子（到其父节点的边）
	for _, x := range q { // 遍历所有叶子
