class Solution {
    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0];
            int y = e[1];
            g[x].add(y);
            g[y].add(x);
        }

        int[] xor = new int[n];
        int[] in = new int[n];
        int[] out = new int[n];
        dfs(0, -1, g, nums, xor, in, out);

        int ans = Integer.MAX_VALUE;
        // 枚举：删除 x 与 x 父节点之间的边，删除 y 与 y 父节点之间的边
        for (int x = 2; x < n; x++) {
            for (int y = 1; y < x; y++) {
                int a, b, c;
                if (isAncestor(x, y, in, out)) { // x 是 y 的祖先
                    a = xor[y];
                    b = xor[x] ^ a;
                    c = xor[0] ^ xor[x];
                } else if (isAncestor(y, x, in, out)) { // y 是 x 的祖先
                    a = xor[x];
                    b = xor[y] ^ a;
                    c = xor[0] ^ xor[y];
                } else { // x 和 y 分别属于两棵不相交的子树
                    a = xor[x];
                    b = xor[y];
                    c = xor[0] ^ a ^ b;
                }
                ans = Math.min(ans, Math.max(Math.max(a, b), c) - Math.min(Math.min(a, b), c));
                if (ans == 0) { // 不可能变小
                    return 0; // 提前返回
                }
            }
        }
        return ans;
    }

    private int clock = 0;

    private void dfs(int x, int fa, List<Integer>[] g, int[] nums, int[] xor, int[] in, int[] out) {
        in[x] = ++clock; // 递
        xor[x] = nums[x];
        for (int y : g[x]) {
            if (y != fa) {
                dfs(y, x, g, nums, xor, in, out);
                xor[x] ^= xor[y];
            }
        }
        out[x] = clock; // 归
    }

    // 判断 x 是否为 y 的祖先
    private boolean isAncestor(int x, int y, int[] in, int[] out) {
        return in[x] < in[y] && in[y] <= out[x];
    }
}
