```java [sol-Java]
class LcaBinaryLifting {
    private final int[] depth;
    public final long[] dis; // 如果是无权树（边权为 1），dis 可以去掉，用 depth 代替
    public final int[][] pa;

    public LcaBinaryLifting(int[][] edges) {
        int n = edges.length + 1;
        int m = 32 - Integer.numberOfLeadingZeros(n); // n 的二进制长度
        List<int[]>[] g = new ArrayList[n];
        Arrays.setAll(g, e -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0], y = e[1], w = e[2];
            g[x].add(new int[]{y, w});
            g[y].add(new int[]{x, w});
        }

        depth = new int[n];
        dis = new long[n];
        pa = new int[n][m];

        dfs(g, 0, -1);

        for (int i = 0; i < m - 1; i++) {
            for (int x = 0; x < n; x++) {
                int p = pa[x][i];
                pa[x][i + 1] = p < 0 ? -1 : pa[p][i];
            }
        }
    }

    private void dfs(List<int[]>[] g, int x, int fa) {
        pa[x][0] = fa;
        for (int[] e : g[x]) {
            int y = e[0];
            if (y != fa) {
                depth[y] = depth[x] + 1;
                dis[y] = dis[x] + e[1];
                dfs(g, y, x);
            }
        }
    }

    public int getKthAncestor(int node, int k) {
        for (; k > 0; k &= k - 1) {
            node = pa[node][Integer.numberOfTrailingZeros(k)];
        }
        return node;
    }

    // 返回 x 和 y 的最近公共祖先（节点编号从 0 开始）
    public int getLCA(int x, int y) {
        if (depth[x] > depth[y]) {
            int tmp = y;
            y = x;
            x = tmp;
        }
        // 使 y 和 x 在同一深度
        y = getKthAncestor(y, depth[y] - depth[x]);
        if (y == x) {
            return x;
        }
        for (int i = pa[x].length - 1; i >= 0; i--) {
            int px = pa[x][i], py = pa[y][i];
            if (px != py) {
                x = px;
                y = py; // 同时往上跳 2^i 步
            }
        }
        return pa[x][0];
    }

    // 返回 x 到 y 的距离（最短路长度）
    public long getDis(int x, int y) {
        return dis[x] + dis[y] - dis[getLCA(x, y)] * 2;
    }

    // 从 x 往上跳【至多】d 距离，返回最远能到达的节点
    public int uptoDis(int x, long d) {
        long dx = dis[x];
        for (int i = pa[x].length - 1; i >= 0; i--) {
            int p = pa[x][i];
            if (p != -1 && dx - dis[p] <= d) { // 可以跳至多 d
                x = p;
            }
        }
        return x;
    }
}

class Solution {
    public int[] findMedian(int n, int[][] edges, int[][] queries) {
        LcaBinaryLifting g = new LcaBinaryLifting(edges);

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int x = queries[i][0];
            int y = queries[i][1];
            if (x == y) {
                ans[i] = x;
                continue;
            }
            int lca = g.getLCA(x, y);
            long disXY = g.dis[x] + g.dis[y] - g.dis[lca] * 2;
            long half = (disXY + 1) / 2;
            if (g.dis[x] - g.dis[lca] >= half) { // 答案在 x-lca 路径中
                // 先往上跳至多 half-1，然后再跳一步，就是至少 half
                int to = g.uptoDis(x, half - 1);
                ans[i] = g.pa[to][0];
            } else { // 答案在 y-lca 路径中
                // 从 y 出发至多 dis_xy-half，就是从 x 出发至少 half
                ans[i] = g.uptoDis(y, disXY - half);
            }
        }
        return ans;
    }
}
