            // 也就意味着 y 已经 merge 到它和 x 的 lca 上了
            // 此时 find(y) 就是 x 和 y 的 lca
            if (y === x || color[y] === 2) {
                diff[x] += 1;
                diff[y] += 1;
                const lca = find(y);
                diff[lca] -= 1;
                if (father[lca] >= 0) {
                    diff[father[lca]] -= 1;
                }
