    }
    tarjan(0, -1);
    
    function dfs(x, fa) {
        let not_halve = 0;
        let halve = 0;
        let cnt = diff[x];
        for (const y of g[x]) {
            if (y !== fa) {
                const [nh, h, c] = dfs(y, x); // 计算 y 不变/减半的最小价值总和
                not_halve += Math.min(nh, h); // x 不变，那么 y 可以不变，可以减半，取这两种情况的最小值
                halve += nh; // x 减半，那么 y 只能不变
                cnt += c; // 自底向上累加差分值
