# 超时了！请看方法二！
class Solution:
    def goodSubtreeSum(self, vals: List[int], par: List[int]) -> int:
        D = 10
        n = len(par)
        g = [[] for _ in range(n)]
        for i in range(1, n):
            g[par[i]].append(i)

        ans = 0

        def dfs(x: int) -> List[int]:
            max_score = [0] * (1 << D)

            # 计算 vals[x] 的数位集合 mask
            mask = 0
            v = vals[x]
            while v:
                v, d = divmod(v, D)
                if mask >> d & 1:
                    break
                mask |= 1 << d
            else:  # 没有中途 break
                max_score[mask] = vals[x]

            # 同一个 mask 至多选一个，直接取 max
            for y in g[x]:
                fy = dfs(y)
                for i, s in enumerate(fy):
                    max_score[i] = max(max_score[i], s)

            for i in range(3, 1 << D):
                # 枚举 i 的非空真子集 sub
                sub = (i - 1) & i
                while sub:
                    max_score[i] = max(max_score[i], max_score[i ^ sub] + max_score[sub])
                    sub = (sub - 1) & i

            nonlocal ans
            ans += max(max_score)
            return max_score

        dfs(0)
        return ans % 1_000_000_007
