char** letterCombinations(char* digits, int* returnSize) {
    int n = strlen(digits);
    int ansSize = 1;
    for (int i = 0; i < n; i++) {
        ansSize *= digits[i] == '7' || digits[i] == '9' ? 4 : 3;
