        if (i == n) {
            ans[*returnSize] = malloc((n + 1) * sizeof(char));
            strcpy(ans[*returnSize], path);
            (*returnSize)++;
            return;
        }
        const char* s = MAPPING[digits[i] - '0'];
        for (int j = 0; s[j]; j++) {
            path[i] = s[j]; // 直接覆盖
            dfs(i + 1);
        }
    }

    dfs(0);

    free(path);
    return ans;
