    dfs = func(i int) {
        if i == n { // 子集构造完毕
            ans = append(ans, slices.Clone(path)) // 复制 path
            return
        }
        
        // 不选 nums[i]
        dfs(i + 1) // 考虑下一个数 nums[i+1] 选或不选
        
        // 选 nums[i]
        path = append(path, nums[i])
        dfs(i + 1) // 考虑下一个数 nums[i+1] 选或不选
