```go [sol-Go]
func checkEqualPartitions(nums []int, target int64) bool {
	tar := int(target)
	for s := 1; s < 1<<(len(nums)-1); s++ {
		mul1, mul2 := 1, 1
		for i, x := range nums {
			if s>>i&1 > 0 { // i 在集合 s 中
				mul1 = min(mul1*x, tar+1) // 与 tar+1 取 min，防止溢出
			} else { // i 在 s 的补集中
				mul2 = min(mul2*x, tar+1)
			}
		}
		if mul1 == tar && mul2 == tar {
			return true
		}
	}
	return false
}
```

