func maximumRows(mat [][]int, numSelect int) (ans int) {
    m, n := len(mat), len(mat[0])
    mask := make([]int, m)
    for i, row := range mat {
        for j, x := range row {
            mask[i] |= x << j
        }
    }

    for subset := 0; subset < 1<<n; subset++ {
        if bits.OnesCount(uint(subset)) != numSelect {
            continue
        }
        coveredRows := 0
        for _, row := range mask {
            if row&subset == row {
                coveredRows++
            }
        }
        ans = max(ans, coveredRows)
    }
    return
}
