	g := make([][]int, n)
	for _, e := range edges {
		x, y := e[0], e[1]
		g[x] = append(g[x], y)
		g[y] = append(g[y], x)
	}

	// 枚举节点集合 U = {0,1,2,...,n-1} 的非空子集 sub
	u := 1<<n - 1
	for sub := 1; sub <= u; sub++ {
