        for (int x : nums) {
            cnt.merge(x, 1, Integer::sum);
        }

        int ans = 1;
        for (Map.Entry<Integer, Integer> e : cnt.entrySet()) {
            int x = e.getKey();
            if (cnt.containsKey(x - k)) { // x 不是等差数列的首项
                continue;
            }
            // 计算这一组的方案数
