            int f1 = 1 << e.getValue();
            for (x += k; cnt.containsKey(x); x += k) {
                int newF = f1 + f0 * ((1 << cnt.get(x)) - 1);
                f0 = f1;
                f1 = newF;
            }
            ans *= f1; // 每组方案数相乘
        }
        return ans - 1; // 去掉空集
    }
}
