func beautifulSubsets(nums []int, k int) int {
	cnt := map[int]int{}
	for _, x := range nums {
		cnt[x]++
	}

	ans := 1
	for x, c := range cnt {
		if cnt[x-k] > 0 { // x 不是等差数列的首项
			continue
		}
