		f0, f1 := 1, 1<<c
		for x += k; cnt[x] > 0; x += k {
			f0, f1 = f1, f1+f0*(1<<cnt[x]-1)
		}
		ans *= f1 // 每组方案数相乘
	}
	return ans - 1 // 去掉空集
}
