func splitString(s string) bool {
next:
	for i := 1; i < len(s); i++ {
		v, _ := strconv.Atoi(s[:i]) // 如果 s 很长，会返回最大 int
		v--
		for t := s[i:]; t != ""; v-- {
			// 移除前导零，但不能全部移除，至少保留一位数字
			for len(t) > 1 && t[0] == '0' {
				t = t[1:]
			}
			// 判断 v 是否符合
			tmp := strconv.Itoa(v)
			if !strings.HasPrefix(t, tmp) {
				continue next
			}
			t = t[len(tmp):]
		}
		return true
	}
	return false
}
