func combinationSum3(k, n int) (ans [][]int) {
    path := []int{}

    var dfs func(int, int)
    dfs = func(i, leftSum int) {
        d := k - len(path) // 还要选 d 个数
        if leftSum < 0 || leftSum > (i*2-d+1)*d/2 { // 剪枝
            return
        }
        if d == 0 { // 找到一个合法组合
            ans = append(ans, slices.Clone(path))
            return
        }
        // 枚举的数不能太小，否则后面没有数可以选
        for j := i; j >= d; j-- {
            path = append(path, j)
            dfs(j-1, leftSum-j)
            path = path[:len(path)-1] // 恢复现场
        }
    }

    dfs(9, n)
    return
}
