class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        path = [0] * n
        ans = []

        # 枚举 path[i] 填 remain（剩余数字）中的哪个数
        def dfs(i: int, remain: Set[int]) -> None:
            if i == n:
                ans.append(path.copy())
                return

            for x in remain:
                path[i] = x
                dfs(i + 1, remain - {x})

        dfs(0, set(nums))
        return ans
