class Solution {
public:
    int findMinimumTime(vector<int>& strength, int k) {
        int ans = numeric_limits<int>::max();
        int n = strength.size();
        vector<int> done(n);
        auto dfs = [&](auto&& dfs, int i, int time) -> void {
            // 剪枝：答案不可能变小
            if (time >= ans) {
                return;
            }
            if (i == n) {
                ans = time;
                return;
            }
            int x = 1 + k * i;
            for (int j = 0; j < n; j++) {
                if (!done[j]) {
                    done[j] = 1; // 已开锁
                    dfs(dfs, i + 1, time + (strength[j] - 1) / x + 1);
                    done[j] = 0; // 恢复现场
                }
            }
        };
        dfs(dfs, 0, 0);
        return ans;
    }
};
