            } else {
                x := b - '1' // 字符 '1'~'9' 转成数字 0~8
                // 标记行、列、宫包含数字 x
                rowHas[i][x] = true
                colHas[j][x] = true
                subBoxHas[i/3][j/3][x] = true
            }
        }
