## 方法一：暴力枚举

枚举从 $\textit{digits}$ 中选三个数（$A_n^3$ 种选法），分别作为个位数（必须是偶数）、十位数和百位数（不能是 $0$）。把生成的三位数添加到一个哈希集合中。

最后答案为哈希集合的大小。

```py [sol-Python3]
class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        st = set()
        for i, a in enumerate(digits):  # 个位数
            if a % 2:
                continue
            for j, b in enumerate(digits):  # 十位数
                if j == i:
                    continue
                for k, c in enumerate(digits):  # 百位数
                    if c == 0 or k == i or k == j:
                        continue
                    st.add(c * 100 + b * 10 + a)
        return len(st)
```

```py [sol-Python3 permutations]
class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        st = set()
        for a, b, c in permutations(digits, 3):
            if c and a % 2 == 0:
                st.add(c * 100 + b * 10 + a)
        return len(st)
```

```java [sol-Java]
class Solution {
    public int totalNumbers(int[] digits) {
        Set<Integer> set = new HashSet<>();
        int n = digits.length;
        for (int i = 0; i < n; i++) { // 个位数
            int a = digits[i];
            if (a % 2 > 0) {
                continue;
            }
            for (int j = 0; j < n; j++) { // 十位数
                if (j == i) {
                    continue;
                }
                for (int k = 0; k < n; k++) { // 百位数
                    int c = digits[k];
                    if (c == 0 || k == i || k == j) {
                        continue;
                    }
                    set.add(c * 100 + digits[j] * 10 + a);
                }
            }
        }
        return set.size();
    }
}
```

