```java [sol-Java]
class Solution {
    public int[] minDifference(int n, int k) {
        int[] path = new int[k];
        dfs(0, n, path);
        return ans;
    }

    private int minDiff = Integer.MAX_VALUE;
    private int[] ans;

    private void dfs(int i, int n, int[] path) {
        if (i == path.length - 1) {
            // path[0] 最小，n 最大
            if (n - path[0] < minDiff) {
                minDiff = n - path[0];
                path[i] = n;
                ans = path.clone();
            }
            return;
        }
        int low = i == 0 ? 1 : path[i - 1];
        int high = i == 0 ? n : path[0] + minDiff - 1;
        for (int d = low; d <= high && d * d <= n; d++) { // 枚举 n 的因子 d
            if (n % d == 0) {
                path[i] = d; // 直接覆盖，无需恢复现场
                dfs(i + 1, n / d, path);
            }
        }
    }
}
