            int res1 = dfs(i - 1, p * x / g, q / g); // 乘以 nums[i]
            g = gcd(p, q * x);
            int res2 = dfs(i - 1, p / g, q * x / g); // 除以 nums[i]
            int res3 = dfs(i - 1, p, q); // 不变
