```java [sol-Java]
class Solution {
    public long minMergeCost(int[][] lists) {
        int n = lists.length;
        int u = 1 << n;
        int[][] sorted = new int[u][];
        for (int i = 0; i < n; i++) { // 枚举不在 s 中的下标 i
            int highBit = 1 << i;
            for (int s = 0; s < highBit; s++) {
                sorted[highBit | s] = merge(sorted[s], lists[i]);
            }
        }

        long[] f = new long[u];
        for (int i = 3; i < u; i++) {
            if ((i & (i - 1)) == 0) { // i 只包含一个元素，无法分解成两个非空子集
                continue; // f[i] = 0
            }
            f[i] = Long.MAX_VALUE;
            // 枚举 i 的非空真子集 j
            for (int j = i & (i - 1); j > (i ^ j); j = (j - 1) & i) {
                int k = i ^ j; // j 关于 i 的补集是 k
                int medJ = sorted[j][(sorted[j].length - 1) / 2];
                int medK = sorted[k][(sorted[k].length - 1) / 2];
                f[i] = Math.min(f[i], f[j] + f[k] + Math.abs(medJ - medK));
            }
            f[i] += sorted[i].length;
        }

        return f[u - 1];
    }

    // 88. 合并两个有序数组（创建一个新数组）
    private int[] merge(int[] a, int[] b) {
        if (a == null) {
            return b;
        }

        int n = a.length;
        int m = b.length;
        int[] res = new int[n + m];
        int i = 0;
        int j = 0;
        int idx = 0;
        while (i < n || j < m) {
            if (j == m || i < n && a[i] < b[j]) {
                res[idx++] = a[i++];
            } else {
                res[idx++] = b[j++];
            }
        }
        return res;
    }
}
