			medJ := sorted[j][(len(sorted[j])-1)/2]
			medK := sorted[k][(len(sorted[k])-1)/2]
			f[i] = min(f[i], f[j]+f[k]+abs(medJ-medK))
		}
		f[i] += len(a)
