class Solution {
public:
    long long minMergeCost(vector<vector<int>>& lists) {
        int n = lists.size();
        int u = 1 << n;
        vector<int> sum_len(u);
        for (int i = 0; i < n; i++) {
            int high_bit = 1 << i;
            for (int s = 0; s < high_bit; s++) {
                sum_len[high_bit | s] = sum_len[s] + lists[i].size();
            }
        }

        vector<int> median(u);
        for (int mask = 0; mask < u; mask++) {
            int sl = sum_len[mask];

            auto check = [&](int med) -> bool {
                int cnt = 0;
                for (int i = 0; i < n; i++) {
                    if ((mask >> i & 1) == 0) {
                        continue;
                    }
                    cnt += ranges::upper_bound(lists[i], med) - lists[i].begin();
                    if (cnt >= (sl + 1) / 2) {
                        return true;
                    }
                }
                return false;
            };

            int left = -1e9 - 1, right = 1e9;
            while (left + 1 < right) {
                int mid = left + (right - left) / 2;
                (check(mid) ? right : left) = mid;
            }
            median[mask] = right;
        }

        vector<long long> f(u);
        for (int i = 3; i < u; i++) {
            if ((i & (i - 1)) == 0) {
                continue;
            }
            f[i] = LLONG_MAX;
            for (int j = i & (i - 1); j > (i ^ j); j = (j - 1) & i) {
                int k = i ^ j;
                f[i] = min(f[i], f[j] + f[k] + abs(median[j] - median[k]));
            }
            f[i] += sum_len[i];
        }

        return f[u - 1];
    }
};
```

```go [sol-Go]
func minMergeCost(lists [][]int) int64 {
	u := 1 << len(lists)
	sumLen := make([]int, u)
	for i, a := range lists {
		highBit := 1 << i
		for s, sl := range sumLen[:highBit] {
			sumLen[highBit|s] = sl + len(a)
		}
	}

	median := make([]int, u)
	for mask, sl := range sumLen {
		k := (sl + 1) / 2
		left, right := int(-1e9), int(1e9)
		median[mask] = left + sort.Search(right-left, func(med int) bool {
			med += left
			cnt := 0
			for s := uint32(mask); s > 0; s &= s - 1 {
				i := bits.TrailingZeros32(s)
				cnt += sort.SearchInts(lists[i], med+1)
				if cnt >= k {
					return true
				}
			}
			return false
		})
	}

	f := make([]int, u)
	for i, sl := range sumLen {
		if i&(i-1) == 0 {
			continue
		}
		f[i] = math.MaxInt
		for j := i & (i - 1); j > i^j; j = (j - 1) & i {
			k := i ^ j
			f[i] = min(f[i], f[j]+f[k]+abs(median[j]-median[k]))
		}
		f[i] += sl
	}
	return int64(f[u-1])
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
