- 空间复杂度：$\mathcal{O}(2^n)$。

## 预处理写法三：meet in the middle

把 $\textit{lists}$ 均分成两部分，分别用写法一算出 $\textit{sorted}_1$ 和 $\textit{sorted}_2$。

设 $n$ 是 $\textit{lists}$ 的长度，$m = \left\lfloor\dfrac{n}{2}\right\rfloor$。

对于正二进制数 $i$：

- 低 $m$ 位：这些数组合并后的大数组，从 $\textit{sorted}_1$ 中获取到。
- 其余高 $n-m$ 位：这些数组合并后的大数组，从 $\textit{sorted}_2$ 中获取到。

然后用 [4. 寻找两个正序数组的中位数](https://leetcode.cn/problems/median-of-two-sorted-arrays/) 求出这两个大数组的中位数，见[【图解】循序渐进：从双指针到二分](https://leetcode.cn/problems/median-of-two-sorted-arrays/solutions/2950686/tu-jie-xun-xu-jian-jin-cong-shuang-zhi-z-p2gd/)。

```py [sol-Python3]
# 手写 min max 更快
min = lambda a, b: b if b < a else a
max = lambda a, b: b if b > a else a

class Solution:
    def calcSorted(self, lists: List[List[int]]) -> List[List[int]]:
        u = 1 << len(lists)
        sorted_ = [[] for _ in range(u)]
        for i, a in enumerate(lists):
            high_bit = 1 << i
            for s in range(high_bit):
                b = sorted_[s] + a
                b.sort()  # 手动合并不如库函数
                sorted_[high_bit | s] = b
        return sorted_

    # 4. 寻找两个正序数组的中位数
    def findMedianSortedArrays(self, a: List[int], b: List[int]) -> float:
        if len(a) > len(b):
            a, b = b, a

        m, n = len(a), len(b)
        # 循环不变量：a[left] <= b[j+1]
        # 循环不变量：a[right] > b[j+1]
        left, right = -1, m
        while left + 1 < right:  # 开区间 (left, right) 不为空
            i = (left + right) // 2
            j = (m + n - 3) // 2 - i
            if a[i] <= b[j + 1]:
                left = i  # 缩小二分区间为 (i, right)
            else:
                right = i  # 缩小二分区间为 (left, i)

        # 此时 left 等于 right-1
        # a[left] <= b[j+1] 且 a[right] > b[j'+1] = b[j]，所以答案是 i=left
        i = left
        j = (m + n - 3) // 2 - i
        ai = a[i] if i >= 0 else -inf
        bj = b[j] if j >= 0 else -inf
        return max(ai, bj)

    def minMergeCost(self, lists: List[List[int]]) -> int:
        n = len(lists)
        m = n // 2
        sorted1 = self.calcSorted(lists[:m])
        sorted2 = self.calcSorted(lists[m:])

        u = 1 << n
        half = (1 << m) - 1
        median = [0] * u
        for i in range(1, u):
            # 把 i 分成低 m 位和高 n-m 位
            # 低 half 位去 sorted1 中找合并后的数组
            # 高 n-half 位去 sorted2 中找合并后的数组
            median[i] = self.findMedianSortedArrays(sorted1[i & half], sorted2[i >> m])

        f = [inf] * u
        for i in range(1, u):
            if i & (i - 1) == 0:
                f[i] = 0
                continue
            j = i & (i - 1)
            while j > (i ^ j):
                k = i ^ j
                f[i] = min(f[i], f[j] + f[k] + abs(median[j] - median[k]))
                j = (j - 1) & i
            f[i] += len(sorted1[i & half]) + len(sorted2[i >> m])

        return f[-1]
```

```java [sol-Java]
class Solution {
    public long minMergeCost(int[][] lists) {
        int n = lists.length;
        int m = n / 2;
        int[][] sorted1 = calcSorted(lists, 0, m);
        int[][] sorted2 = calcSorted(lists, m, n - m);

        int u = 1 << n;
        int half = (1 << m) - 1;
        int[] median = new int[u];
        for (int i = 1; i < u; i++) {
            // 把 i 分成低 m 位和高 n-m 位
            // 低 half 位去 sorted1 中找合并后的数组
            // 高 n-half 位去 sorted2 中找合并后的数组
            median[i] = findMedianSortedArrays(sorted1[i & half], sorted2[i >> m]);
        }

        long[] f = new long[u];
        for (int i = 3; i < u; i++) {
            if ((i & (i - 1)) == 0) {
                continue;
            }
            f[i] = Long.MAX_VALUE;
            for (int j = i & (i - 1); j > (i ^ j); j = (j - 1) & i) {
                int k = i ^ j;
                f[i] = Math.min(f[i], f[j] + f[k] + Math.abs(median[j] - median[k]));
            }
            f[i] += sorted1[i & half].length + sorted2[i >> m].length;
        }

        return f[u - 1];
    }

    private int[][] calcSorted(int[][] lists, int start, int n) {
        int u = 1 << n;
        int[][] sorted = new int[u][];
        sorted[0] = new int[]{};
        for (int i = 0; i < n; i++) {
            int highBit = 1 << i;
            for (int s = 0; s < highBit; s++) {
                sorted[highBit | s] = merge(sorted[s], lists[start + i]);
            }
        }
        return sorted;
    }

    // 88. 合并两个有序数组（创建一个新数组）
    private int[] merge(int[] a, int[] b) {
        if (a == null) {
            return b;
        }

        int n = a.length;
        int m = b.length;
        int[] res = new int[n + m];
        int i = 0;
        int j = 0;
        int idx = 0;
        while (i < n || j < m) {
            if (j == m || i < n && a[i] < b[j]) {
                res[idx++] = a[i++];
            } else {
                res[idx++] = b[j++];
            }
        }
        return res;
    }

    // 4. 寻找两个正序数组的中位数
    private int findMedianSortedArrays(int[] a, int[] b) {
        if (a.length > b.length) {
            // 交换 a 和 b
            int[] tmp = a;
            a = b;
            b = tmp;
        }

        int m = a.length;
        int n = b.length;
        // 循环不变量：a[left] <= b[j+1]
        // 循环不变量：a[right] > b[j+1]
        int left = -1;
        int right = m;
        while (left + 1 < right) { // 开区间 (left, right) 不为空
            int i = left + (right - left) / 2;
            int j = (m + n + 1) / 2 - i - 2;
            if (a[i] <= b[j + 1]) {
                left = i; // 缩小二分区间为 (i, right)
            } else {
                right = i; // 缩小二分区间为 (left, i)
            }
        }

        // 此时 left 等于 right-1
        // a[left] <= b[j+1] 且 a[right] > b[j'+1] = b[j]，所以答案是 i=left
        int i = left;
        int j = (m + n + 1) / 2 - i - 2;
        int ai = i >= 0 ? a[i] : Integer.MIN_VALUE;
        int bj = j >= 0 ? b[j] : Integer.MIN_VALUE;
        return Math.max(ai, bj);
    }
}
