```cpp [sol-C++]
class Solution {
    // 88. 合并两个有序数组（创建一个新数组）
    vector<int> merge(const vector<int>& a, const vector<int>& b) {
        int n = a.size(), m = b.size();
        vector<int> res;
        res.reserve(n + m);
        int i = 0, j = 0;
        while (i < n || j < m) {
            if (j == m || i < n && a[i] < b[j]) {
                res.push_back(a[i++]);
            } else {
                res.push_back(b[j++]);
            }
        }
        return res;
    }

    vector<vector<int>> calc_sorted(const vector<vector<int>>& lists, int begin, int n) {
        int u = 1 << n;
        vector<vector<int>> sorted(u);
        for (int i = 0; i < n; i++) {
            int high_bit = 1 << i;
            for (int s = 0; s < high_bit; s++) {
                sorted[high_bit | s] = merge(sorted[s], lists[begin + i]);
            }
        }
        return sorted;
    }

    // 4. 寻找两个正序数组的中位数
    int findMedianSortedArrays(const vector<int>& a, const vector<int>& b) {
        if (a.size() > b.size()) {
            return findMedianSortedArrays(b, a);
        }

        int m = a.size(), n = b.size();
        // 循环不变量：a[left] <= b[j+1]
        // 循环不变量：a[right] > b[j+1]
        int left = -1, right = m;
        while (left + 1 < right) { // 开区间 (left, right) 不为空
            int i = left + (right - left) / 2;
            int j = (m + n + 1) / 2 - i - 2;
            if (a[i] <= b[j + 1]) {
                left = i; // 缩小二分区间为 (i, right)
            } else {
                right = i; // 缩小二分区间为 (left, i)
            }
        }

        // 此时 left 等于 right-1
        // a[left] <= b[j+1] 且 a[right] > b[j'+1] = b[j]，所以答案是 i=left
        int i = left;
        int j = (m + n + 1) / 2 - i - 2;
        int ai = i >= 0 ? a[i] : INT_MIN;
        int bj = j >= 0 ? b[j] : INT_MIN;
        return max(ai, bj);
    }

public:
