```go [sol-Go]
// 88. 合并两个有序数组（创建一个新数组）
func merge(a, b []int) []int {
	i, n := 0, len(a)
	j, m := 0, len(b)
	res := make([]int, 0, n+m)
	for {
		if i == n {
			return append(res, b[j:]...)
		}
		if j == m {
			return append(res, a[i:]...)
		}
		if a[i] < b[j] {
			res = append(res, a[i])
			i++
		} else {
			res = append(res, b[j])
			j++
		}
	}
}

func calcSorted(lists [][]int) [][]int {
	u := 1 << len(lists)
	sorted := make([][]int, u)
	for i, a := range lists {
		highBit := 1 << i
		for s, b := range sorted[:highBit] {
			sorted[highBit|s] = merge(a, b)
		}
	}
	return sorted
}

// 4. 寻找两个正序数组的中位数
func findMedianSortedArrays(a, b []int) int {
	if len(a) > len(b) {
		a, b = b, a
	}

	m, n := len(a), len(b)
	i := sort.Search(m, func(i int) bool {
		j := (m+n+1)/2 - i - 2
		return a[i] > b[j+1]
	}) - 1

	j := (m+n+1)/2 - i - 2
	if i < 0 {
		return b[j]
	}
	if j < 0 {
		return a[i]
	}
	return max(a[i], b[j])
}

func minMergeCost(lists [][]int) int64 {
	n := len(lists)
	m := n / 2
	sorted1 := calcSorted(lists[:m])
	sorted2 := calcSorted(lists[m:])

	u := 1 << n
	half := 1<<m - 1
	median := make([]int, u)
	for i := 1; i < u; i++ {
		// 把 i 分成低 m 位和高 n-m 位
		// 低 half 位去 sorted1 中找合并后的数组
		// 高 n-half 位去 sorted2 中找合并后的数组
		median[i] = findMedianSortedArrays(sorted1[i&half], sorted2[i>>m])
	}

	f := make([]int, u)
	for i := range f {
		if i&(i-1) == 0 {
			continue
		}
		f[i] = math.MaxInt
		for j := i & (i - 1); j > i^j; j = (j - 1) & i {
			k := i ^ j
			f[i] = min(f[i], f[j]+f[k]+abs(median[j]-median[k]))
		}
		f[i] += len(sorted1[i&half]) + len(sorted2[i>>m])
	}
	return int64(f[u-1])
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
