## 优化

把 $x=\textit{nums}[i]$ 的数位拆开，放入一个数组 $a$ 中。例如 $x=123$ 拆开得到 $a=[3,2,1]$，注意低位在数组左边，这样下标与 $10$ 的幂次可以对应上。

交换 $a[i]$ 和 $a[j]$，相当于 $x$ 增加了

$$
\begin{aligned}
    & (a[j]-a[i])\cdot 10^i + (a[i]-a[j]) \cdot 10^j      \\
={} & (a[j]-a[i])(10^i-10^j)        \\
\end{aligned}
$$

这样就不需要把字符串再转成数字了，预处理 $10^i$ 后，可以 $\mathcal{O}(1)$ 算出交换后的数字。

此外，我们可以在 $a[i]=a[j]$ 时，直接 `continue`，因为交换不改变 $x$ 的值。

```py [sol-Python3]
POW10 = [10 ** i for i in range(7)]

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        nums.sort()
        ans = 0
        cnt = defaultdict(int)
        for x in nums:
            st = {x}  # 不交换
            a = list(map(int, str(x)))[::-1]
            m = len(a)
            for i in range(m):
                for j in range(i + 1, m):
                    if a[i] == a[j]:  # 小优化
                        continue
                    y = x + (a[j] - a[i]) * (POW10[i] - POW10[j])
                    st.add(y)  # 交换一次
                    a[i], a[j] = a[j], a[i]
                    for p in range(i + 1, m):
                        for q in range(p + 1, m):
                            st.add(y + (a[q] - a[p]) * (POW10[p] - POW10[q]))  # 交换两次
                    a[i], a[j] = a[j], a[i]
            ans += sum(cnt[v] for v in st)
            cnt[x] += 1
        return ans
```

```java [sol-Java]
class Solution {
    private static final int[] POW10 = {1, 10, 100, 1000, 10000, 100000, 1000000};

    public int countPairs(int[] nums) {
        Arrays.sort(nums);
        int ans = 0;
        Map<Integer, Integer> cnt = new HashMap<>();
        int[] a = new int[7];
        for (int x : nums) {
            Set<Integer> st = new HashSet<>();
            st.add(x); // 不交换
            int m = 0;
            for (int v = x; v > 0; v /= 10) {
                a[m++] = v % 10;
            }
            for (int i = 0; i < m; i++) {
                for (int j = i + 1; j < m; j++) {
                    if (a[i] == a[j]) { // 小优化
                        continue;
                    }
                    int y = x + (a[j] - a[i]) * (POW10[i] - POW10[j]);
                    st.add(y); // 交换一次
                    swap(a, i, j);
                    for (int p = i + 1; p < m; p++) {
                        for (int q = p + 1; q < m; q++) {
                            st.add(y + (a[q] - a[p]) * (POW10[p] - POW10[q])); // 交换两次
                        }
                    }
                    swap(a, i, j);
                }
            }
            for (int v : st) {
                ans += cnt.getOrDefault(v, 0);
            }
            cnt.merge(x, 1, Integer::sum);
        }
        return ans;
    }

    private void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}
