class Solution {
    public int beautifulSplits(int[] nums) {
        int n = nums.length;
        int ans = 0;
        int[] z0 = calcZ(nums, 0);
        for (int i = 1; i < n - 1; i++) {
            int[] z = calcZ(nums, i);
            for (int j = i + 1; j < n; j++) {
                if (i <= j - i && z0[i] >= i || z[j - i] >= j - i) {
                    ans++;
                }
            }
        }
        return ans;
    }

    private int[] calcZ(int[] s, int start) {
        int n = s.length - start;
        int[] z = new int[n];
        int boxL = 0;
        int boxR = 0; // z-box 左右边界
        for (int i = 1; i < n; i++) {
            if (i <= boxR) {
                z[i] = Math.min(z[i - boxL], boxR - i + 1);
            }
            while (i + z[i] < n && s[start + z[i]] == s[start + i + z[i]]) {
                boxL = i;
                boxR = i + z[i];
                z[i]++;
            }
        }
        return z;
    }
}
