            ans_left = i;
        }

        // 3. 右端点离开窗口，为下一个循环做准备
        hash = (hash - (s[right] & 31) * p % mod + mod) % mod; // +mod 保证非负
    }

    char* ans = malloc(k + 1);
    strncpy(ans, s + ans_left, k);
    ans[k] = '\0';
    return ans;
}
