impl Solution {
    pub fn find_length(nums1: Vec<i32>, nums2: Vec<i32>) -> i32 {
        let mut ans = 0;
        let mut f = vec![vec![0; nums2.len() + 1]; nums1.len() + 1];
        for (i, x) in nums1.into_iter().enumerate() {
            for (j, &y) in nums2.iter().enumerate() {
                if x == y {
                    f[i + 1][j + 1] = f[i][j] + 1;
                    ans = ans.max(f[i + 1][j + 1]);
                }
            }
        }
        ans
    }
