public:
    int minimumGroups(vector<string>& words) {
        unordered_set<string> st;

        for (auto& word : words) {
            // 按照下标的奇偶性分组
            string groups[2]{};
            for (int i = 0; i < word.size(); i++) {
                groups[i % 2] += word[i];
            }

            // 分别计算偶数组和奇数组的最小表示
            string min_s(word.size(), 0);
            for (int k = 0; k < 2; k++) {
                auto s = smallestRepresentation(groups[k]);
                for (int j = 0; j < s.size(); j++) {
                    min_s[j * 2 + k] = s[j];
                }
            }

            st.insert(min_s);
        }

        return st.size();
    }
};
