    int minimumGroups(vector<string>& words) {
        unordered_set<string> st;

        for (auto& word : words) {
            // 按照下标的奇偶性分组
            string groups[2]{};
            for (int i = 0; i < word.size(); i++) {
                groups[i % 2] += word[i];
