class Solution {
    public long numGoodSubarrays(int[] nums, int k) {
        long ans = subarraysDivByK(nums, k);
        int n = nums.length;
        int start = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            if (i < n - 1 && x == nums[i + 1]) {
                continue;
            }
            // 遍历到了连续相同元素段的末尾
            int size = i - start + 1; // 这一段的长度
            for (int sz = 1; sz <= size; sz++) {
                if ((long) x * sz % k == 0) {
                    // 长为 sz 的子数组元素和能被 k 整除
                    // 一共有 size-sz+1 个长为 sz 的子数组，其中有 size-sz 个重复的
                    ans -= size - sz;
                }
            }
            start = i + 1;
        }
        return ans;
    }

    // 974. 和可被 K 整除的子数组
    // 由于本题 nums 没有负数，无需调整
    private long subarraysDivByK(int[] nums, int k) {
        Map<Integer, Integer> cnt = new HashMap<>(nums.length, 1); // 预分配空间
        int s = 0;
        long ans = 0;
        for (int x : nums) {
            cnt.merge(s, 1, Integer::sum); // cnt[s]++
            s = (s + x) % k;
            ans += cnt.getOrDefault(s, 0);
        }
        return ans;
    }
}
