class Solution {
    public int findRotateSteps(String S, String T) {
        char[] s = S.toCharArray();
        char[] t = T.toCharArray();
        int n = s.length;
        int m = t.length;
        boolean[][] vis = new boolean[n][m + 1];
        vis[0][0] = true;
        List<int[]> q = List.of(new int[]{0, 0});
        for (int step = 0; ; step++) {
            List<int[]> tmp = q;
            q = new ArrayList<>();
            for (int[] p : tmp) {
                int i = p[0], j = p[1];
                if (j == m) {
                    return step;
