                    if (!vis[i][j + 1]) {
                        vis[i][j + 1] = true;
                        q.add(new int[]{i, j + 1});
                    }
                    continue;
                }
                for (int i2 : new int[]{(i - 1 + n) % n, (i + 1) % n}) {
                    if (!vis[i2][j]) {
                        vis[i2][j] = true;
                        q.add(new int[]{i2, j});
                    }
                }
            }
        }
    }
