func continuousSubarrays(nums []int) (ans int64) {
	cnt := map[int]int{}
	left := 0
	for right, x := range nums {
		cnt[x]++
		for {
			mx, mn := x, x
			for k := range cnt {
				mx = max(mx, k)
				mn = min(mn, k)
			}
			if mx-mn <= 2 {
				break
			}
			out := nums[left]
			cnt[out]--
			if cnt[out] == 0 {
				delete(cnt, out)
			}
			left++
		}
		ans += int64(right - left + 1)
	}
	return
}
