                min_q.pop_back();
            }
            min_q.push_back(right);

            while (!max_q.empty() && x >= nums[max_q.back()]) {
                max_q.pop_back();
            }
            max_q.push_back(right);

            while (nums[max_q.front()] - nums[min_q.front()] > 2) {
                left++;
                if (min_q.front() < left) {
                    min_q.pop_front();
                }
                if (max_q.front() < left) {
                    max_q.pop_front();
                }
            }
            ans += right - left + 1;
        }
        return ans;
    }
