```cpp [sol-C++ 写法二]
class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        unordered_multiset<int> st(nums1.begin(), nums1.end());
        vector<int> ans;
        for (int x : nums2) {
            auto it = st.find(x);
            if (it != st.end()) {
                st.erase(it);
                ans.push_back(x);
            }
        }
        return ans;
    }
};
```

