            if (d != num.charAt(i - 1)) {
                cnt = 1;
                continue;
            }
            cnt++;
            if (cnt == 3 && d > mx) {
                mx = d;
            }
        }
        return mx > 0 ? String.valueOf(mx).repeat(3) : "";
    }
}
```

