func findMaxPathScore(edges [][]int, online []bool, k int64) int {
	n := len(online)
	type edge struct{ to, wt int }
	g := make([][]edge, n)
	deg := make([]int, n)
	maxWt := -1
	for _, e := range edges {
		x, y, wt := e[0], e[1], e[2]
		if online[x] && online[y] {
			g[x] = append(g[x], edge{y, wt})
			deg[y]++
			if x == 0 {
				maxWt = max(maxWt, wt)
			}
		}
	}

	// 先清理无法从 0 到达的边
	q := []int{}
	for i := 1; i < n; i++ {
		if deg[i] == 0 {
			q = append(q, i)
