	ans := sort.Search(maxWt+1, func(lower int) bool {
		deg := slices.Clone(deg)
		for i := 1; i < n; i++ {
			f[i] = math.MaxInt / 2 // 除 2 防止加法溢出
		}

		q := []int{0}
		for len(q) > 0 {
			x := q[0]
			if x == n-1 {
				return f[x] > int(k)
			}
			q = q[1:]
			for _, e := range g[x] {
				y := e.to
				wt := e.wt
				if wt >= lower {
					f[y] = min(f[y], f[x]+wt)
				}
				deg[y]--
				if deg[y] == 0 {
					q = append(q, y)
				}
			}
		}
		return true
	}) - 1
	return ans
}
```

#### 复杂度分析

- 时间复杂度：$\mathcal{O}((n + m)\log U)$，其中 $n$ 是 $\textit{online}$ 的长度，$m$ 是 $\textit{edges}$ 的长度，$U$ 是边权的最大值。
- 空间复杂度：$\mathcal{O}(n + m)$。

