        def check(d: int) -> bool:
            # 二分最小的 f(d+1) < k，从而知道最大的 f(d) >= k
            d += 1
            cnt = 1
            pre = price[0]  # 先选一个价格最小的糖果
            for p in price:
                if p - pre >= d:  # 可以选 p
                    cnt += 1
                    pre = p
            return cnt < k

