public:
    int maximumSafenessFactor(vector<vector<int>>& grid) {
        int n = grid.size();
        vector dis(n, vector<int>(n, -1));
        vector<pair<int, int>> q;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) {
                    dis[i][j] = 0;
                    q.emplace_back(i, j);
                }
            }
        }

        vector<vector<pair<int, int>>> groups = {q};
        // 多源 BFS
        while (!q.empty()) {
            auto tmp = move(q);
            for (auto& [i, j] : tmp) {
                for (auto& [dx, dy] : dirs) {
                    int x = i + dx, y = j + dy;
                    if (0 <= x && x < n && 0 <= y && y < n && dis[x][y] < 0) {
                        dis[x][y] = groups.size();
                        q.emplace_back(x, y);
                    }
                }
            }
            groups.push_back(q); // 相同 dis 分组记录
        }

        // 并查集模板
        vector<int> fa(n * n);
        ranges::iota(fa, 0);
        auto find = [&](this auto&& find, int x) -> int { 
            return fa[x] == x ? x : fa[x] = find(fa[x]);
        };

        // 从大到小枚举答案
        for (int ans = (int) groups.size() - 2; ans > 0; ans--) {
            for (auto& [i, j] : groups[ans]) {
                for (auto& [dx, dy] : dirs) {
                    int x = i + dx, y = j + dy;
                    if (0 <= x && x < n && 0 <= y && y < n && dis[x][y] >= ans) {
                        fa[find(x * n + y)] = find(i * n + j);
                    }
                }
            }
            if (find(0) == find(n * n - 1)) { // 写这里判断更快些
                return ans;
            }
        }
        return 0;
    }
};
