public:
    int maxStability(int n, vector<vector<int>>& edges, int k) {
        UnionFind must_uf(n); // 必选边并查集
        UnionFind all_uf(n); // 全图并查集
        int min_s = INT_MAX, max_s = 0;
        for (auto& e : edges) {
            int x = e[0], y = e[1], s = e[2], must = e[3];
            if (must && !must_uf.merge(x, y)) { // 必选边成环
                return -1;
            }
            all_uf.merge(x, y);
            min_s = min(min_s, s);
            max_s = max(max_s, s);
        }

        if (all_uf.cc > 1) { // 图不连通
            return -1;
        }

        auto check = [&](int low) -> bool {
            UnionFind u(n);
            for (auto& e : edges) {
                int x = e[0], y = e[1], s = e[2], must = e[3];
                if (must && s < low) { // 必选边的边权太小
                    return false;
                }
                if (must || s >= low) {
                    u.merge(x, y);
                }
            }

            int left_k = k;
            for (auto& e : edges) {
                if (left_k == 0 || u.cc == 1) {
                    break;
                }
                int x = e[0], y = e[1], s = e[2], must = e[3];
                if (!must && s < low && s * 2 >= low && u.merge(x, y)) {
                    left_k--;
                }
            }
            return u.cc == 1;
        };

        int left = min_s, right = max_s * 2 + 1;
        while (left + 1 < right) {
            int mid = left + (right - left) / 2;
            (check(mid) ? left : right) = mid;
        }
        return left;
    }
