	x, y := u.find(from), u.find(to)
	if x == y { // from 和 to 在同一个集合，不做合并
		return false
	}
	u.fa[x] = y // 合并集合。修改后就可以认为 from 和 to 在同一个集合了
	u.cc--      // 成功合并，连通块个数减一
	return true
}

func maxStability(n int, edges [][]int, k int) int {
	mustUf := newUnionFind(n) // 必选边并查集
	allUf := newUnionFind(n) // 全图并查集
	minS, maxS := math.MaxInt, 0
	for _, e := range edges {
		x, y, s, must := e[0], e[1], e[2], e[3]
		if must > 0 && !mustUf.merge(x, y) { // 必选边成环
			return -1
		}
		allUf.merge(x, y)
		minS = min(minS, s)
		maxS = max(maxS, s)
	}

	if allUf.cc > 1 { // 图不连通
		return -1
	}

	check := func(low int) bool {
		u := newUnionFind(n)
		for _, e := range edges {
			x, y, s, must := e[0], e[1], e[2], e[3]
			if must > 0 && s < low { // 必选边的边权太小
				return false
			}
			if must > 0 || s >= low {
				u.merge(x, y)
			}
		}

		leftK := k
		for _, e := range edges {
			if leftK == 0 || u.cc == 1 {
				break
			}
			x, y, s, must := e[0], e[1], e[2], e[3]
			if must == 0 && s < low && s*2 >= low && u.merge(x, y) {
				leftK--
			}
		}
		return u.cc == 1
	}

	left, right := minS, maxS*2+1
	for left+1 < right {
		mid := left + (right-left)/2
		if check(mid) {
			left = mid
		} else {
			right = mid
		}
	}
	return left
}
