class UnionFind {
    private final int[] fa; // 代表元
    public int cc; // 连通块个数

    UnionFind(int n) {
        // 一开始有 n 个集合 {0}, {1}, ..., {n-1}
        // 集合 i 的代表元是自己
        fa = new int[n];
        for (int i = 0; i < n; i++) {
            fa[i] = i;
        }
        cc = n;
    }

    // 返回 x 所在集合的代表元
    // 同时做路径压缩，也就是把 x 所在集合中的所有元素的 fa 都改成代表元
    public int find(int x) {
        // 如果 fa[x] == x，则表示 x 是代表元
        if (fa[x] != x) {
            fa[x] = find(fa[x]); // fa 改成代表元
        }
        return fa[x];
    }

    // 把 from 所在集合合并到 to 所在集合中
    // 返回是否合并成功
    public boolean merge(int from, int to) {
        int x = find(from);
        int y = find(to);
        if (x == y) { // from 和 to 在同一个集合，不做合并
            return false;
        }
        fa[x] = y; // 合并集合。修改后就可以认为 from 和 to 在同一个集合了
        cc--; // 成功合并，连通块个数减一
        return true;
    }
}

class Solution {
    public int maxStability(int n, int[][] edges, int k) {
        UnionFind uf = new UnionFind(n);
        UnionFind allUf = new UnionFind(n);
        int minS1 = Integer.MAX_VALUE;
        for (int[] e : edges) {
            int x = e[0], y = e[1], s = e[2], must = e[3];
            if (must > 0) {
                if (!uf.merge(x, y)) { // 必选边成环
                    return -1;
                }
                minS1 = Math.min(minS1, s);
            }
            allUf.merge(x, y);
        }

        if (allUf.cc > 1) { // 图不连通
            return -1;
        }

        if (uf.cc == 1) { // 只需选必选边
            return minS1;
        }

        // Kruskal 求最大生成树
        Arrays.sort(edges, (a, b) -> b[2] - a[2]);
        List<Integer> a = new ArrayList<>();
        for (int[] e : edges) {
            int x = e[0], y = e[1], s = e[2], must = e[3];
            if (must == 0 && uf.merge(x, y)) {
                a.add(s);
            }
        }

        // 答案为如下三者的最小值：
        // 1. must = 1 中的最小边权
        // 2. a 中最小边权 * 2
        // 3. a 中第 k+1 小边权
        int m = a.size();
        int ans = Math.min(minS1, a.get(m - 1) * 2);
        if (k < m) {
            ans = Math.min(ans, a.get(m - 1 - k));
        }
        return ans;
    }
}
