template<typename T>
struct VectorHash {
    static void hash_combine(size_t& seed, const T& v) {
        // 参考 boost::hash_combine
        seed ^= hash<T>{}(v) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
    }

    size_t operator()(const vector<T>& vec) const {
        size_t seed = 0;
        for (const T& v : vec) {
            hash_combine(seed, v);
        }
        return seed;
    }
};

