```cpp [sol-C++]
class Solution {
    int encode(vector<int>& nums, vector<int>& sorted) {
        int res = 0;
        for (int i = 0; i < nums.size(); i++) {
            int x = ranges::lower_bound(sorted, nums[i]) - sorted.begin();
            res |= x << (i * 3);
