```java [sol-Java]
class Solution {
    public boolean isPalindromic(String s) {
        char[] chars = s.toCharArray();
        StringBuilder t = new StringBuilder(chars.length * 8);
        for (char ch : chars) {
            t.append(String.format("%8s", Integer.toBinaryString(ch)).replace(' ', '0'));
        }

        int n = t.length();
        for (int i = 0; i < n / 2; i++) {
            if (t.charAt(i) != t.charAt(n - 1 - i)) {
                return false;
            }
        }
        return true;
    }
}
```

```cpp [sol-C++]
class Solution {
public:
    bool isPalindromic(string s) {
        string t;
        for (char ch : s) {
            for (int i = 7; i >= 0; i--) {
                t += '0' + (ch >> i & 1);
            }
        }

        int n = t.size();
        for (int i = 0; i < n / 2; i++) {
            if (t[i] != t[n - 1 - i]) {
                return false;
            }
        }
        return true;
    }
};
