func sortByReflection(nums []int) []int {
	slices.SortFunc(nums, func(a, b int) int {
		revA := int(bits.Reverse(uint(a)) >> bits.LeadingZeros(uint(a)))
		revB := int(bits.Reverse(uint(b)) >> bits.LeadingZeros(uint(b)))
