}

func pow(x, n, mod int) int {
    res := 1 % mod // 注意 mod 可能等于 1
    for ; n > 0; n /= 2 {
        if n%2 > 0 {
            res = res * x % mod
        }
        x = x * x % mod
    }
    return res
