func findProductsOfElements(queries [][]int64) []int {
    ans := make([]int, len(queries))
    for i, q := range queries {
        er := sumE(int(q[1]) + 1)
        el := sumE(int(q[0]))
        ans[i] = pow(2, er-el, int(q[2]))
    }
    return ans
}
