	for i, p := range subSum {
		j := u ^ i
		if p.and+subSum[j].or*2-subSum[j].xor > ans { // 有机会让 ans 变得更大
			ans = max(ans, p.and+maxXor2(uint(j)))
		}
	}
	return int64(ans)
}
```

#### 复杂度分析

- 时间复杂度：$\mathcal{O}(n2^n\log U)$，其中 $n$ 是 $\textit{nums}$ 的长度，$U=\max(\textit{nums})$。
- 空间复杂度：$\mathcal{O}(2^n + \log U)$。

