```go [sol-Go]
func minPathSum(grid [][]int) int {
    m, n := len(grid), len(grid[0])
    f := make([][]int, m+1)
    for i := range f {
        f[i] = make([]int, n+1)
    }
    for j := range f[0] {
        f[0][j] = math.MaxInt
    }
    for i, row := range grid {
        f[i+1][0] = math.MaxInt
        for j, x := range row {
            if i == 0 && j == 0 {
                f[1][1] = x
            } else {
                f[i+1][j+1] = min(f[i+1][j], f[i][j+1]) + x
            }
        }
    }
    return f[m][n]
}
```

