```go [sol-Go]
func minFallingPathSum(matrix [][]int) int {
    n := len(matrix)
    memo := make([][]int, n)
    for i := range memo {
        memo[i] = make([]int, n)
        for j := range memo[i] {
            memo[i][j] = math.MinInt
        }
    }
    var dfs func(int, int) int
    dfs = func(r, c int) int {
        if c < 0 || c >= n { // 出界
            return math.MaxInt
        }
        if r == 0 { // 到达第一行
            return matrix[0][c]
        }
        p := &memo[r][c]
        if *p == math.MinInt { // 没有计算过
            *p = min(min(dfs(r-1, c-1), dfs(r-1, c)), dfs(r-1, c+1)) + matrix[r][c]
        }
        return *p
    }
    ans := math.MaxInt
    for c := range n {
        ans = min(ans, dfs(n-1, c))
    }
    return ans
}
