func minFallingPathSum(matrix [][]int) int {
    f := append(append([]int{math.MaxInt}, matrix[0]...), math.MaxInt)
    for _, row := range matrix[1:] {
        pre := f[0]
        for c, x := range row {
            pre, f[c+1] = f[c+1], min(pre, min(f[c+1], f[c+2]))+x
        }
    }
