```js [sol-JavaScript]
var minFallingPathSum = function(matrix) {
    const n = matrix.length, inf = Number.MAX_SAFE_INTEGER;
    let f = [inf, ...matrix[0], inf];
    for (let r = 1; r < n; r++) {
        let pre = f[0];
        for (let c = 0; c < n; c++)
            [pre, f[c + 1]] = [f[c + 1], Math.min(pre, f[c + 1], f[c + 2]) + matrix[r][c]];
    }
    return Math.min(...f); // 也可以 _.min(f);
};
