```go [sol-Go]
func minPathCost(grid [][]int, moveCost [][]int) int {
    m, n := len(grid), len(grid[0])
    memo := make([][]int, m)
    for i := range memo {
        memo[i] = make([]int, n)
    }
    var dfs func(int, int) int
    dfs = func(i, j int) int {
        if i == m-1 { // 递归边界
            return grid[i][j]
        }
        p := &memo[i][j]
        if *p != 0 { // 之前计算过
            return *p
        }
        res := math.MaxInt
        for k, c := range moveCost[grid[i][j]] { // 移动到下一行的第 k 列
            res = min(res, dfs(i+1, k)+c)
        }
        *p = res + grid[i][j] // 记忆化
        return *p
    }
    ans := math.MaxInt
    for j := 0; j < n; j++ { // 枚举起点
        ans = min(ans, dfs(0, j))
    }
    return ans
}
