```rust [sol-Rust]
impl Solution {
    pub fn min_path_cost(mut grid: Vec<Vec<i32>>, move_cost: Vec<Vec<i32>>) -> i32 {
        let m = grid.len();
        let n = grid[0].len();
        let mut f = vec![vec![i32::MAX; n]; m];
        f[m - 1] = grid[m - 1].clone();
        for i in (0..m - 1).rev() {
            for (j, &g) in grid[i].iter().enumerate() {
                f[i][j] = g + f[i + 1]
                    .iter()
                    .zip(move_cost[g as usize].iter())
                    .map(|(&v, &c)| v + c)
                    .min()
                    .unwrap();
            }
        }
        *f[0].iter().min().unwrap()
    }
}
