func minPathCost(grid [][]int, moveCost [][]int) int {
    for i := len(grid) - 2; i >= 0; i-- {
        for j, g := range grid[i] {
            res := math.MaxInt
            for k, c := range moveCost[g] {
                res = min(res, grid[i+1][k]+c)
            }
            grid[i][j] += res
        }
    }
    return slices.Min(grid[0])
}
