```js [sol-JavaScript]
var minPathCost = function(grid, moveCost) {
    const m = grid.length, n = grid[0].length;
    for (let i = m - 2; i >= 0; i--) {
        for (let j = 0; j < n; j++) {
            let res = Infinity;
            for (let k = 0; k < n; k++) {
                res = Math.min(res, grid[i + 1][k] + moveCost[grid[i][j]][k]);
            }
            grid[i][j] += res;
        }
    }
    return Math.min(...grid[0]);
};
