```rust [sol-Rust]
impl Solution {
    pub fn min_path_cost(mut grid: Vec<Vec<i32>>, move_cost: Vec<Vec<i32>>) -> i32 {
        let m = grid.len();
        let n = grid[0].len();
        for i in (0..m - 1).rev() {
            for j in 0..n {
                grid[i][j] += grid[i + 1]
                    .iter()
                    .zip(move_cost[grid[i][j] as usize].iter())
                    .map(|(&g, &c)| g + c)
                    .min()
                    .unwrap();
            }
        }
        *grid[0].iter().min().unwrap()
    }
}
