			for k := range K + 1 {
				newK := k
				if x > 0 {
					newK--
				}
				f[i+1][j+1][k+1] = max(f[i][j+1][newK+1], f[i+1][j][newK+1]) + x
			}
		}
	}

	ans := f[m][n][K+1]
	if ans < 0 {
		return -1
	}
	return ans
}
