    public int maxPathScore(int[][] grid, int K) {
        int n = grid[0].length;
        int[][] f = new int[n + 1][K + 2];
        for (int[] row : f) {
            Arrays.fill(row, Integer.MIN_VALUE);
        }
        Arrays.fill(f[1], 1, K + 2, 0);

        for (int[] row : grid) {
            for (int j = 0; j < n; j++) {
