class Solution:
    def uniquePaths(self, grid: List[List[int]]) -> int:
        MOD = 1_000_000_007
        n = len(grid[0])
        # 2*(n+1) 比 (n+1)*2 快（可以对比 Python3 写法二）
        f0 = [0] * (n + 1)
