                    f0[j + 1] = (f0[j] + f1[j + 1]) % MOD
                    f1[j + 1] = f0[j + 1]
                else:
                    f0[j + 1] = f1[j + 1]
                    f1[j + 1] = f0[j]
        return f0[n]
