class Solution:
    def numberOfPaths(self, grid: List[List[int]], k: int) -> int:
        MOD = 1_000_000_007
        m, n = len(grid), len(grid[0])
        f = [[0] * k for _ in range(n + 1)]
        f[1][0] = 1
        for row in grid:
            for j, x in enumerate(row):
                new_f = [0] * k  # 为避免提前把 f[j+1][s] 覆盖，先保存到 new_f[s] 中
                for s in range(k):
