        // 300. 最长递增子序列
        List<Integer> g = new ArrayList<>();
        for (int[] e : envelopes) {
            int h = e[1];
            int j = Collections.binarySearch(g, h);
            if (j < 0) {
                j = ~j;
            }
            if (j < g.size()) {
                g.set(j, h);
            } else {
                g.add(h);
            }
        }
        return g.size();
    }
