	f := make([]int, m)
	for i := range m {
		for j := range i {
			// 如果 f[j] <= f[i]，就不用跑 O(n) 的 lessEq 了
			if f[j] > f[i] && lessEq(j, i) {
				f[i] = f[j]
			}
		}
		f[i]++
	}
	return m - slices.Max(f)
}
