```js [sol-JavaScript]
var minDeletionSize = function(strs) {
    // 对于每一行，j 列的字母都 <= i 列的字母？
    function lessEq(j, i) {
        for (const s of strs) {
            if (s[j] > s[i]) {
                return false;
            }
        }
        return true;
    }

    const m = strs[0].length;
    const f = Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < i; j++) {
            // 如果 f[j] <= f[i]，就不用跑 O(n) 的 lessEq 了
            if (f[j] > f[i] && lessEq(j, i)) {
                f[i] = f[j];
            }
        }
        f[i]++;
    }
    return m - Math.max(...f);
};
