class Solution {
    // 354. 俄罗斯套娃信封问题
    int maxEnvelopes(vector<pair<int, int>>& envelopes) {
        ranges::sort(envelopes, {}, [](auto& e) { return pair(e.first, -e.second); });

        vector<int> g;
        for (auto& [_, h] : envelopes) {
            auto it = ranges::upper_bound(g, h); // 允许 LIS 相邻元素相等
            if (it != g.end()) {
                *it = h;
            } else {
                g.push_back(h);
            }
        }
        return g.size();
    }

