func getWordsInLongestSubsequence(words []string, groups []int) []string {
	n := len(words)
	fMap := map[int]struct{ maxF, j, maxF2, j2 int }{}
	from := make([]int, n)
	maxF, maxI := 0, 0
	for i := n - 1; i >= 0; i-- {
		w, g := words[i], groups[i]

		// 计算 w 的哈希值
		hash := 0
		for _, ch := range w {
			hash = hash<<5 | int(ch&31)
		}

		f := 0 // 方法一中的 f[i]
		for j := range w {
			h := hash | 31<<(j*5) // 用记号笔把 w[k] 涂黑（置为 11111）
			t := fMap[h]
			if g != groups[t.j] { // 可以从最大值转移过来
				if t.maxF > f {
					f = t.maxF
					from[i] = t.j
				}
			} else { // 只能从次大值转移过来
				if t.maxF2 > f {
					f = t.maxF2
					from[i] = t.j2
				}
			}
		}

		f++
		if f > maxF {
			maxF, maxI = f, i
		}

		// 用 f 更新 fMap[h] 的最大次大
		// 注意要保证最大次大的 group 值不同
		for j := range w {
			h := hash | 31<<(j*5)
			t := fMap[h]
			if f > t.maxF { // 最大值需要更新
				if g != groups[t.j] {
					t.maxF2 = t.maxF // 旧最大值变成次大值
					t.j2 = t.j
				}
				t.maxF = f
				t.j = i
			} else if f > t.maxF2 && g != groups[t.j] { // 次大值需要更新
				t.maxF2 = f
				t.j2 = i
			}
			fMap[h] = t
		}
	}

	ans := make([]string, maxF)
	i := maxI
	for k := range ans {
		ans[k] = words[i]
		i = from[i]
	}
	return ans
}
