class Solution {
public:
    int minCut(string s) {
        int n = s.size();
        vector pal_memo(n, vector<int>(n, -1)); // -1 表示没有计算过
        auto is_palindrome = [&](this auto&& is_palindrome, int l, int r) -> bool {
            if (l >= r) {
                return true;
