func maxSubarraySum(nums []int, k int) int64 {
	solve := func(isMul bool) int64 {
		res := int64(math.MinInt)
		var f0, f1, f2 int64
		for _, x := range nums {
			x := int64(x)
			y := x
			if isMul {
				y *= int64(k)
			} else {
				y /= int64(k)
			}
			f2 = max(f1, f2) + x
			f1 = max(f0, f1, 0) + y
			f0 = max(f0, 0) + x
			res = max(res, f1, f2)
		}
		return res
	}
	return max(solve(true), solve(false))
}
