            f2 = Math.max(f2, maxF1) + (x == k ? 1 : 0);
            f1[x] = Math.max(f1[x], f0) + 1;
            f0 += (x == k ? 1 : 0);
            maxF1 = Math.max(maxF1, f1[x]);
        }
        return Math.max(maxF1, f2);
    }
}
