                    f0 = MAX(f0, 0) + 1;
                    f1++;
                } else if (s[i] == b) {
                    f1 = f0 = MAX(f0, 0) - 1;
                } // else f0 = MAX(f0, 0); 可以留到 ch 等于 a 或者 b 的时候计算，f1 不变
                ans = MAX(ans, f1);
            }
        }
    }
    return ans;
}
