                        f0 = f0.max(0) + 1;
                        f1 += 1;
                    } else if ch == b {
                        f1 = f0.max(0) - 1;
                        f0 = f1;
                    } // else { f0 = f0.max(0); } 可以留到 ch 等于 a 或者 b 的时候计算，f1 不变
                    ans = ans.max(f1);
                }
            }
        }
        ans
    }
