```go [sol-Go]
const mod = 1_000_000_007
const maxN = 100_001

var pow2 = [maxN]int{1}

func init() {
	// 预处理 2 的幂
	for i := 1; i < maxN; i++ {
		pow2[i] = pow2[i-1] * 2 % mod
	}
}

func countEffective(nums []int) int {
	or := 0
	same := true
	for _, x := range nums {
		or |= x
		if x != nums[0] {
			same = false
		}
	}
	// 优化：如果 nums 只有一种数字，那么非空子序列的按位或都是 or，只有空子序列的按位或比 or 小
	if same {
		return 1
	}

	w := bits.Len(uint(or))
	f := make([]int, 1<<w)
	for _, x := range nums {
		f[x]++
	}
	for i := range w {
		if or>>i&1 == 0 { // 优化：or 中是 0 但 s 中是 1 的 f[s] 后面容斥用不到，无需计算
			continue
		}
		for s := 0; s < 1<<w; s++ {
			s |= 1 << i
			f[s] += f[s^1<<i]
		}
	}
	// 计算完毕后，f[s] 表示 nums 中的是 s 的子集的元素个数

	ans := pow2[len(nums)] // 所有子序列的个数
	// 枚举 or 的所有子集（包括空集）
	for sub, ok := or, true; ok; ok = sub != or {
		sign := 1 - bits.OnesCount(uint(or^sub))%2*2
		ans -= sign * pow2[f[sub]]
		sub = (sub - 1) & or
	}
	return (ans%mod + mod) % mod // 保证结果非负
}
