    const n = nums.length;
    const q = Array(n); // 为方便起见，仍然用一个大小为 n 的数组（空间 O(k) 需要实现环形队列）
    let head = 0, tail = 0;
    q[tail++] = 0;
    for (let i = 1; i < n; i++) {
        // 1. 出
        if (q[head] < i - k) {
            head++;
        }
        // 2. 转移
        nums[i] += nums[q[head]];
        // 3. 入
        while (head < tail && nums[i] >= nums[q[tail - 1]]) {
            tail--;
        }
        q[tail++] = i;
    }
    return nums[n - 1];
};
```

