use std::collections::VecDeque;

impl Solution {
    pub fn max_result(mut nums: Vec<i32>, k: i32) -> i32 {
        let n = nums.len();
        let k = k as usize;
        let mut q = VecDeque::new();
        q.push_back(0);
        for i in 1..n {
            // 1. 出
            if *q.front().unwrap() + k < i {
                q.pop_front();
            }
            // 2. 转移
            nums[i] += nums[*q.front().unwrap()];
            // 3. 入
            while !q.is_empty() && nums[i] >= nums[*q.back().unwrap()] {
                q.pop_back();
            }
            q.push_back(i);
        }
        nums[n - 1]
    }
}
