func maximumSum(nums []int, m, left, right int) int64 {
	n := len(nums)
	s := make([]int, n+1) // nums 的前缀和
	for i, x := range nums {
		s[i+1] = s[i] + x
	}

	// f[i][j] 表示在前 j 个数（下标 0 到 j-1）中选出恰好 i 个子数组，所选元素之和的最大值
	f := make([][]int, m+1)
	f[0] = make([]int, n+1)
	ans := math.MinInt

	for i := 1; i <= m; i++ {
		f[i] = make([]int, n+1)
		for j := range f[i] {
			f[i][j] = math.MinInt / 2
		}
		q := []int{}

		// 前 i 个子数组至少占用了 i * left 个位置
		for j := i * left; j <= n; j++ {
			// 1. 入
			k := j - left
			v := f[i-1][k] - s[k]
			for len(q) > 0 && f[i-1][q[len(q)-1]]-s[q[len(q)-1]] <= v {
				q = q[:len(q)-1]
			}
			q = append(q, k)

