```go [sol-Go]
func maximumJumps(nums []int, target int) int {
	n := len(nums)
	memo := make([]int, n)

	var dfs func(int) int
	dfs = func(j int) int {
		if j == 0 { // 起点
			return 0
		}

		p := &memo[j]
		if *p != 0 { // 之前计算过
			return *p
		}

		res := math.MinInt
		for i, x := range nums[:j] {
			if abs(x-nums[j]) <= target { // 可以从 i 跳到 j
				res = max(res, dfs(i)+1)
			}
		}
		*p = res // 记忆化
		return res
	}

	ans := dfs(n - 1) // 终点
	if ans < 0 {
		return -1
	}
	return ans
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
