```go [sol-Go]
func maxWeight(n int, edges [][]int, k int, t int) int {
	if n <= k {
		return -1
	}

	type edge struct{ to, wt int }
	g := make([][]edge, n)
	for _, e := range edges {
		x, y, wt := e[0], e[1], e[2]
		g[x] = append(g[x], edge{y, wt})
	}

	ans := -1
	type tuple struct{ x, i, s int }
	vis := map[tuple]bool{}
	var dfs func(int, int, int)
	dfs = func(x, i, s int) {
		if i == k {
			ans = max(ans, s)
			return
		}
		args := tuple{x, i, s}
		if vis[args] { // 访问过
			return
		}
		vis[args] = true
		for _, e := range g[x] {
			if s+e.wt < t {
				dfs(e.to, i+1, s+e.wt)
			}
		}
	}
	for x := range n { // 枚举起点
		dfs(x, 0, 0)
	}
	return ans
}
