```go [sol-Go]
func maxWeight(n int, edges [][]int, k int, t int) int {
	if n <= k {
		return -1
	}

	type edge struct{ to, wt int }
	g := make([][]edge, n)
	deg := make([]int, n)
	for _, e := range edges {
		x, y, wt := e[0], e[1], e[2]
		g[x] = append(g[x], edge{y, wt})
	}

	ans := -1
	f := make([][]map[int]struct{}, n)
	for i := range f {
		f[i] = make([]map[int]struct{}, k+1)
		for j := range f[i] {
			f[i][j] = map[int]struct{}{}
		}
	}
	q := []int{}
	for i, d := range deg {
		if d == 0 {
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		x := q[0]
		q = q[1:]
		f[x][0][0] = struct{}{} // x 单独一个点，路径边权和为 0
		for s := range f[x][k] { // 恰好 k 条边
			ans = max(ans, s)
		}
		for _, e := range g[x] {
			y, wt := e.to, e.wt
			for i, st := range f[x][:k] {
				for s := range st {
					if s+wt < t {
						f[y][i+1][s+wt] = struct{}{}
					}
				}
			}
			deg[y]--
			if deg[y] == 0 {
				q = append(q, y)
			}
		}
	}
	return ans
}
