        }

        vector f(k + 1, vector<unordered_set<int>>(n));
        for (int i = 0; i < n; i++) {
            f[0][i].insert(0);
        }
        for (int i = 0; i < k; i++) {
            for (auto& e : edges) {
                int x = e[0], y = e[1], wt = e[2];
                for (int s : f[i][x]) {
                    if (s + wt < t) {
                        f[i + 1][y].insert(s + wt);
                    }
                }
            }
        }

        int ans = -1;
        for (auto& st : f[k]) {
            for (int s : st) {
                ans = max(ans, s);
            }
        }
        return ans;
    }
};
