class Solution {
public:
    int maxWeight(int n, vector<vector<int>>& edges, int k, int t) {
        if (n <= k) {
            return -1;
        }

        vector f(k + 1, vector<bitset<600>>(n));
        for (int i = 0; i < n; i++) {
            f[0][i].set(0);
        }
        for (int i = 0; i < k; i++) {
            for (auto& e : edges) {
                int x = e[0], y = e[1], wt = e[2];
                if (!f[i][x].none()) {
                    f[i + 1][y] |= f[i][x] << wt;
                }
            }
        }

        int ans = -1;
        for (auto& bs : f[k]) {
            for (int s = t - 1; s >= 0; s--) {
                if (bs[s]) {
                    ans = max(ans, s);
                    break;
                }
            }
        }
        return ans;
    }
};
