                    st.insert(i);
                    int sz = min(j - left1[i][j], down1[i][j] - i); // min(左,下)
                    to_remove[i + sz - 1].push_back(i); // 在未来移除

                    // (i,j) 作为正方形的左下角
                    // 找 sl 中的大于 i-size 的最小横坐标 i2
                    sz = min(right1[i][j] - j, i - up1[i][j]); // min(右,上)
