```go [sol-Go]
func findSquare(matrix [][]int) []int {
    n := len(matrix)
    // 预处理每个格子左右上下最近的 1 的位置
    left1 := make([][]int, n)
    right1 := make([][]int, n)
    up1 := make([][]int, n)
    down1 := make([][]int, n)
    for i := range n {
        left1[i] = make([]int, n)
        right1[i] = make([]int, n)
        up1[i] = make([]int, n)
        down1[i] = make([]int, n)
    }

    for i, row := range matrix {
        l := -1
        for j, x := range row {
            if x == 1 {
                l = j
            }
            left1[i][j] = l
        }

        r := n
        for j := n - 1; j >= 0; j-- {
            if row[j] == 1 {
                r = j
            }
            right1[i][j] = r
        }
    }

    for j := range n {
        u := -1
        for i, row := range matrix {
            if row[j] == 1 {
                u = i
            }
            up1[i][j] = u
        }

        d := n
        for i := n - 1; i >= 0; i-- {
            if matrix[i][j] == 1 {
                d = i
            }
            down1[i][j] = d
        }
    }

    var maxSize, minR, minC int

    for k := range n*2 - 1 {
        set := redblacktree.New[int, struct{}]()
        toRemove := make([][]int, n)
        minJ := max(k-n+1, 0)
        maxJ := min(k, n-1)

        for j := maxJ; j >= minJ; j-- {
            i := k - j
            if matrix[i][j] == 0 {
                // (i,j) 作为正方形的右上角，可以服务于左下角横坐标在 [i,i+sz-1] 中的正方形
                set.Put(i, struct{}{})
                sz := min(j-left1[i][j], down1[i][j]-i) // min(左,下)
                toRemove[i+sz-1] = append(toRemove[i+sz-1], i)

                // (i,j) 作为正方形的左下角
                // 找 sl 中的大于 i-size 的最小横坐标 i2
                sz = min(right1[i][j]-j, i-up1[i][j]) // min(右,上)
                node, _ := set.Ceiling(i - sz + 1)
                i2 := node.Key
                size := i - i2 + 1
                if size > maxSize || size == maxSize && (i2 < minR || i2 == minR && j < minC) {
                    maxSize, minR, minC = size, i2, j
                }
            }

            // 移除那些超过服务范围的右上角横坐标
            for _, i2 := range toRemove[i] {
                set.Remove(i2)
            }
        }
    }

    if maxSize == 0 {
        return nil
    }
    return []int{minR, minC, maxSize}
}
