	n := len(nums)
	s := make([]int, n+1)
	cnt := redblacktree.New[int, int]() // "github.com/emirpasic/gods/v2/trees/redblacktree"
	for j := 1; j <= n; j++ {
		s[j] = s[j-1] + nums[j-1]
		if j < l {
			continue
		}
		c, _ := cnt.Get(s[j-l])
		cnt.Put(s[j-l], c+1)
