```go [sol-Go]
func longestCommonPrefix(arr1, arr2 []int) int {
	has := map[int]bool{}
	for _, x := range arr1 {
		for x > 0 && !has[x] { // 如果 x 在 st 中，那么剩余前缀也在 st 中
			has[x] = true
			x /= 10
		}
	}

	mx := 0
	for _, x := range arr2 {
		for x > 0 && !has[x] {
			x /= 10
		}
		mx = max(mx, x)
	}

	if mx == 0 {
		return 0
	}
	return len(strconv.Itoa(mx))
}
