```py [sol-Python3]
# 预处理 core
MX = 100_001
core = [0] * MX
for i in range(1, MX):
    if core[i] == 0:
        for j in range(1, isqrt(MX // i) + 1):
            core[i * j * j] = i

class Solution:
    def sumOfAncestors(self, n: int, edges: List[List[int]], nums: List[int]) -> int:
        g = [[] for _ in range(n)]
        for x, y in edges:
            g[x].append(y)
            g[y].append(x)

        cnt = defaultdict(int)
        ans = 0

        def dfs(x: int, fa: int) -> None:
            nonlocal ans
            c = core[nums[x]]
            # 本题 x 的祖先不包括 x 自己
            ans += cnt[c]
            cnt[c] += 1
            for y in g[x]:
                if y != fa:
                    dfs(y, x)
            cnt[c] -= 1  # 恢复现场

        dfs(0, -1)
        return ans
```

```java [sol-Java]
class Solution {
    private static final int MX = 100_001;
    private static final int[] core = new int[MX];

    static {
        // 预处理 core
        for (int i = 1; i < MX; i++) {
            if (core[i] == 0) {
                for (int j = 1; i * j * j < MX; j++) {
                    core[i * j * j] = i;
                }
            }
        }
    }

    public long sumOfAncestors(int n, int[][] edges, int[] nums) {
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0], y = e[1];
            g[x].add(y);
            g[y].add(x);
        }

        Map<Integer, Integer> cnt = new HashMap<>(); // 更快的写法见【Java 数组】
        return dfs(0, -1, g, nums, cnt);
    }

    private long dfs(int x, int fa, List<Integer>[] g, int[] nums, Map<Integer, Integer> cnt) {
        int cr = core[nums[x]];
        // 本题 x 的祖先不包括 x 自己
        int c = cnt.getOrDefault(cr, 0);
        long res = c;
        cnt.put(cr, c + 1);
        for (int y : g[x]) {
            if (y != fa) {
                res += dfs(y, x, g, nums, cnt);
            }
        }
        cnt.put(cr, c); // 恢复现场
        return res;
    }
}
```

```java [sol-Java 数组]
class Solution {
    private static final int MX = 100_001;
    private static final int[] core = new int[MX];

    static {
        // 预处理 core
        for (int i = 1; i < MX; i++) {
            if (core[i] == 0) {
                for (int j = 1; i * j * j < MX; j++) {
                    core[i * j * j] = i;
                }
            }
        }
    }

    public long sumOfAncestors(int n, int[][] edges, int[] nums) {
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0], y = e[1];
            g[x].add(y);
            g[y].add(x);
        }

        int mx = 0;
        for (int x : nums) {
            mx = Math.max(mx, core[x]);
        }

        int[] cnt = new int[mx + 1];
        return dfs(0, -1, g, nums, cnt);
    }

    private long dfs(int x, int fa, List<Integer>[] g, int[] nums, int[] cnt) {
        int cr = core[nums[x]];
        // 本题 x 的祖先不包括 x 自己
        long res = cnt[cr]++;
        for (int y : g[x]) {
            if (y != fa) {
                res += dfs(y, x, g, nums, cnt);
            }
        }
        cnt[cr]--; // 恢复现场
        return res;
    }
}
